window.LLM_INLINE_EXAMS = {"Chapter_2_Exercise_Dataset.ipynb": {"page": "llm_chapter_2_subjective_test", "cells": [{"number": 1, "code_number": 1, "type": "code", "source": "import importlib\nimport tiktoken\n\nprint(\"tiktoken version:\", importlib.metadata.version(\"tiktoken\"))\n\ntokenizer = tiktoken.get_encoding(\"gpt2\")\n\ntext = (\n    \"Hello, do you like tea? <|endoftext|> In the sunlit terraces\"\n     \"of someunknownPlace.\"\n)\n# region  [token encoding]\n# TODO: 인코딩 메서드명을 채워 text를 토큰 ID로 변환하세요.\n# 힌트: `????`에는 문자열을 토큰 ID 리스트로 바꾸는 인코딩 메서드 이름이 들어갑니다.\n# 힌트: `tokenizer.` 뒤 메서드 이름만 채우고 `allowed_special` 설정은 그대로 두면 됩니다.\nintegers = tokenizer.[[BLANK:blank-token-encode]](text, allowed_special={\"<|endoftext|>\"})\n# endregion\nprint(integers)\n\n# region  [token decoding]\n# TODO: 디코딩 메서드명을 채워 토큰 ID를 문자열로 복원하세요.\n# 힌트: `????`에는 토큰 ID 리스트를 다시 문자열로 바꾸는 디코딩 메서드 이름이 들어갑니다.\n# 힌트: `tokenizer.` 뒤 메서드 이름만 채우고 입력은 `integers` 그대로 사용하세요.\nstrings = tokenizer.[[BLANK:blank-token-decode]](integers)\n# endregion\nprint(strings)"}, {"number": 2, "code_number": 2, "type": "code", "source": "import os\nimport requests\n%pip install torch\nos.makedirs(\"datas\", exist_ok=True)\nif not os.path.exists(\"datas/the-verdict.txt\"):\n    url = (\n        \"https://raw.githubusercontent.com/rasbt/\"\n        \"LLMs-from-scratch/main/ch02/01_main-chapter-code/\"\n        \"the-verdict.txt\"\n    )\n    file_path = \"datas/the-verdict.txt\"\n\n    response = requests.get(url, timeout=30)\n    response.raise_for_status()\n    with open(file_path, \"wb\") as f:\n        f.write(response.content)\nwith open(\"datas/the-verdict.txt\", \"r\", encoding=\"utf-8\") as f:\n    raw_text = f.read()\n    \nenc_text = tokenizer.encode(raw_text)\nprint(len(enc_text))\n\nenc_sample = enc_text[50:]\n\ncontext_size = 4\n\n# TODO: y 시퀀스가 x보다 한 칸 오른쪽으로 미루도록 인덱스를 채우세요.\n# 힌트: 첫 번째 `????`에는 시작 인덱스를 한 칸 미루는 값 `1`이 들어갑니다.\n# 힌트: 두 번째 `?????`에도 끝 인덱스를 한 칸 늘리는 값 `1`이 들어가며, y는 x의 next-token 시퀀스가 됩니다.\nx = enc_sample[:context_size]\ny = enc_sample[[[BLANK:blank-next-token-start]]:context_size+[[BLANK:blank-next-token-end]]]\n\nprint(f\"x: {x}\")\nprint(f\"y:      {y}\")"}, {"number": 3, "code_number": 3, "type": "code", "source": "### 중요: 이 코드는 GPT 모델 학습을 위한 데이터셋 클래스를 정의합니다\n\nimport torch\nfrom torch.utils.data import Dataset, DataLoader\n\nclass GPTDatasetV1(Dataset):\n    def __init__(self, txt, tokenizer, max_length, stride):\n        \"\"\"\n        Args:\n            txt (str): 학습할 전체 텍스트 데이터\n            tokenizer: 텍스트를 토큰 ID로 변환해주는 토크나이저 (예: tiktoken)\n            max_length (int): 모델이 한 번에 볼 수 있는 윈도우 크기 (입력 시퀀스 길이)\n            stride (int): 윈도우를 이동시킬 간격 (데이터 중복 정도를 결정)\n        \"\"\"\n        self.input_ids = []\n        self.target_ids = []\n\n        # 1. 전체 텍스트 토큰화\n        # 텍스트를 정수 리스트(token_ids)로 변환합니다.\n        # <|endoftext|> 같은 특수 토큰도 허용하여 인코딩합니다.\n        token_ids = tokenizer.encode(txt, allowed_special={\"<|endoftext|>\"})\n\n        # 데이터가 너무 짧으면 학습할 수 없으므로 최소 길이를 확인합니다.\n        assert len(token_ids) > max_length, \"토큰화된 입력의 개수는 적어도 max_length+1과 같아야 합니다.\"\n\n        # 2. 슬라이딩 윈도우(Sliding Window)로 데이터 생성\n        # 전체 토큰 리스트를 훑으며 max_length 길이만큼 잘라냅니다.\n        # stride만큼 건너뛰며 반복합니다.\n        for i in range(0, len(token_ids) - max_length, stride):\n            # 입력 청크: 현재 위치(i)부터 max_length만큼 가져옵니다.\n            # region [input 청크 생성]\n            # TODO: 입력 청크 슬라이싱 구간을 채우세요.\n            # 힌트: 첫 번째 `????`는 슬라이싱 시작 위치인 `i`입니다.\n            # 힌트: 두 번째 `????`도 끝 위치 계산에 쓰이는 `i`라서 `i : i + max_length` 형태를 완성하면 됩니다.\n            input_chunk = token_ids[[[BLANK:blank-input-start]] : [[BLANK:blank-input-end]] + max_length]\n            # endregion\n              \n            # 타겟 청크: 입력보다 1칸 뒤의 위치(i+1)부터 가져옵니다.\n            # GPT는 '다음 단어'를 맞추는 모델이므로, 정답은 입력보다 한 칸씩 뒤로 밀려있어야 합니다.\n            # region [target 청크 생성]\n            # TODO: 타깃 청크 슬라이싱 구간을 채우세요.\n            # 힌트: 네 개의 `????`는 순서대로 `i`, `1`, `i`, `1`입니다.\n            # 힌트: 입력보다 한 칸 뒤를 가리키도록 `i + 1 : i + max_length + 1` 형태를 만들면 됩니다.\n            target_chunk = token_ids[[[BLANK:blank-target-start-i]] + [[BLANK:blank-target-start-offset]] : [[BLANK:blank-target-end-i]] + max_length + [[BLANK:blank-target-end-offset]]]\n            # endregion\n\n            # 추출한 데이터를 텐서(Tensor)로 변환하여 리스트에 저장합니다.\n            self.input_ids.append(torch.tensor(input_chunk))\n            self.target_ids.append(torch.tensor(target_chunk))\n\n    def __len__(self):\n        # 데이터셋의 총 샘플(청크) 개수를 반환합니다.\n        return len(self.input_ids)\n\n    def __getitem__(self, idx):\n        # DataLoader가 데이터를 요청할 때 호출됩니다.\n        # 해당 인덱스(idx)의 입력과 정답 쌍을 반환합니다.\n        # TODO: __getitem__에서 같은 idx의 입력/타깃 쌍을 반환하세요.\n        # 힌트: `self.input_ids`와 `self.target_ids`에서 `idx` 위치의 값을 각각 반환하세요.\n        return self.input_ids[idx], self.target_ids[idx]"}, {"number": 4, "code_number": 4, "type": "code", "source": "##중요 : 아래 함수는 DataLoader를 생성하는 헬퍼 함수입니다.\nimport tiktoken\ndef create_dataloader_v1(txt, batch_size=4, max_length=256,\n                         stride=128, shuffle=True, drop_last=True,\n                         num_workers=0):\n\n    # 토크나이저를 초기화합니다.\n    tokenizer = tiktoken.get_encoding(\"gpt2\")\n\n    # 데이터셋을 만듭니다.\n    dataset = GPTDatasetV1(txt, tokenizer, max_length, stride)\n\n    # 데이터 로더를 만듭니다.\n    # region [DataLoader 생성]\n    # TODO: DataLoader의 첫 번째 인자를 채우세요.\n    # 힌트: `????`에는 바로 위에서 생성한 `dataset` 객체가 들어갑니다.\n    # 힌트: DataLoader의 첫 번째 위치 인자는 순회할 데이터셋 자체입니다.\n    dataloader = DataLoader(\n        [[BLANK:blank-dataloader-dataset]],\n        batch_size=batch_size,\n        shuffle=shuffle,\n        drop_last=drop_last,\n        num_workers=num_workers\n    )\n    # endregion\n    \n    return dataloader"}, {"number": 5, "code_number": 5, "type": "code", "source": "dataloader = create_dataloader_v1(\n    raw_text, batch_size=1, max_length=4, stride=1, shuffle=False\n)\n\ndata_iter = iter(dataloader)\n\nfirst_batch = next(data_iter)\nprint(first_batch)\n\nsecond_batch = next(data_iter)\nprint(second_batch)"}, {"number": 6, "code_number": 6, "type": "code", "source": "# DataLoader와 연결된 GPTDatasetV1의 멤버 정보 확인\nprint(f\"DataLoader type: {type(dataloader)}\")\nprint(f\"Dataset type:    {type(dataloader.dataset)}\")\nprint(\"\\n[DataLoader 주요 멤버]\")\nfor name in [\"batch_size\", \"drop_last\", \"num_workers\", \"pin_memory\", \"timeout\"]:\n    value = getattr(dataloader, name)\n    print(f\"{name}: {value!r} (type: {type(value).__name__})\")\nprint(f\"sampler:       {type(dataloader.sampler).__name__}\")\nprint(f\"batch_sampler: {type(dataloader.batch_sampler).__name__}\")\nprint(f\"collate_fn:    {dataloader.collate_fn.__name__}\")\n\ndataset = dataloader.dataset\nprint(\"\\n[GPTDatasetV1 주요 멤버]\")\nprint(f\"input_ids:  {type(dataset.input_ids).__name__}, 샘플 수 = {len(dataset.input_ids)}\")\nprint(f\"target_ids: {type(dataset.target_ids).__name__}, 샘플 수 = {len(dataset.target_ids)}\")\nprint(f\"샘플 input:  dtype={dataset.input_ids[0].dtype}, shape={tuple(dataset.input_ids[0].shape)}\")\nprint(f\"샘플 target: dtype={dataset.target_ids[0].dtype}, shape={tuple(dataset.target_ids[0].shape)}\")\n\ninputs, targets = next(iter(dataloader))\nprint(\"\\n[실제 DataLoader 배치]\")\nprint(f\"inputs:  dtype={inputs.dtype}, shape={tuple(inputs.shape)}\")\nprint(f\"targets: dtype={targets.dtype}, shape={tuple(targets.shape)}\")\nprint(\"의미: inputs/targets의 shape은 [batch_size, max_length]입니다.\")"}, {"number": 7, "code_number": 7, "type": "code", "source": "input_ids = torch.tensor([2, 3, 5, 1])\n\nvocab_size = 6\noutput_dim = 3\n\ntorch.manual_seed(123)\n# region [임베딩 레이어 생성]\n# TODO: Embedding 생성자 인자를 채우세요.\n# 힌트: 첫 번째 `????`는 단어장 크기인 `vocab_size`입니다.\n# 힌트: 두 번째 `????`는 각 토큰 임베딩 벡터의 차원인 `output_dim`입니다.\nembedding_layer = torch.nn.Embedding([[BLANK:blank-embedding-vocab]], [[BLANK:blank-embedding-dim]])\n# endregion\n\nprint(embedding_layer.weight)\n\n# region [임베딩 레이어 적용]\n# TODO: 임베딩 레이어 입력 변수를 채우세요.\n# 힌트: `????`에는 임베딩할 토큰 ID 텐서인 `input_ids`가 들어갑니다.\n# 힌트: Embedding 레이어는 정수 토큰 ID 텐서를 입력으로 받습니다.\ntoken_embeddings = embedding_layer([[BLANK:blank-embedding-input]])\n# endregion\nprint(token_embeddings)"}, {"number": 8, "code_number": 8, "type": "code", "source": "vocab_size = 50257\noutput_dim = 256\n\ntoken_embedding_layer = torch.nn.Embedding(vocab_size, output_dim)\n\nmax_length = 4\ndataloader = create_dataloader_v1(\n    raw_text, batch_size=8, max_length=max_length,\n    stride=max_length, shuffle=False\n)\n\ndata_iter = iter(dataloader)\ninputs, targets = next(data_iter)\ntoken_embeddings = token_embedding_layer(inputs)\nprint(token_embeddings.shape)\n\ncontext_length = max_length\n# region [포지셔널 임베딩 레이어 생성]\npos_embedding_layer = torch.nn.Embedding(context_length, output_dim)\n# endregion\n# region [포지셔널 임베딩 적용]\npos_embeddings = pos_embedding_layer(torch.arange(max_length))\n# endregion\nprint(pos_embeddings.shape)\n# region [토큰 임베딩과 포지셔널 임베딩 합산]\ninput_embeddings = [[BLANK:blank-input-embeddings]]\n# endregion\nprint(input_embeddings.shape)"}, {"number": 9, "code_number": null, "type": "markdown", "source": "## Tokenizer 비교"}, {"number": 10, "code_number": null, "type": "markdown", "source": "- 아래 결과를 보면 한국어는 Exaone, 중국어는 Qwen의 Tokenizer 성능이 좋습니다"}, {"number": 11, "code_number": 9, "type": "code", "source": "from transformers import AutoTokenizer\n# Tokenizer 로드 (로컬 또는 온라인에서)\nprint(\"Tokenizer 로드 중...\")\nqwen = AutoTokenizer.from_pretrained(\"Qwen/Qwen3-0.6B\")\nexaone = AutoTokenizer.from_pretrained(\"LGAI-EXAONE/EXAONE-4.0-1.2B\")\n\n# 테스트할 텍스트\ntexts = [\n    \"안녕하세요, 반갑습니다!\",\n    \"Hello, nice to meet you!\",\n    \"인공지능 기술이 발전하고 있습니다.\",\n    \"Hello! This is an English tokenizer test.\",\n    \"こんにちは！日本語のテストです。\",\n    \"人工智能技术正在快速发展。\",\n    \"The quick brown fox jumps over the lazy dog. 빠른 갈색 여우가 게으른 개를 뛰어넘습니다.\",\n    \"파이썬 프로그래밍은 매우 유용합니다. Python programming is very useful.\",\n    \"123456789 !@#$%^&*() 특수문자\",\n]\n\nprint(\"\\n\" + \"=\"*60)\nfor text in texts:\n    print(f\"\\n텍스트: {text}\")\n    print(\"-\"*60)\n    \n    # Qwen3\n    qwen_tokens = qwen.encode(text, add_special_tokens=True)\n    qwen_token_strs = [qwen.decode([tok]) for tok in qwen_tokens[:10]]\n    print(f\"Qwen3:  {len(qwen_tokens)}개 토큰\")\n    print(f\"        {qwen_token_strs}\")\n    \n    # EXAONE\n    exaone_tokens = exaone.encode(text, add_special_tokens=True)\n    exaone_token_strs = [exaone.decode([tok]) for tok in exaone_tokens[:10]]\n    print(f\"EXAONE: {len(exaone_tokens)}개 토큰\")\n    print(f\"        {exaone_token_strs}\")\n    \n    # 비교\n    diff = len(qwen_tokens) - len(exaone_tokens)\n    if diff > 0:\n        print(f\"→ EXAONE이 {diff}개 더 효율적\")\n    elif diff < 0:\n        print(f\"→ Qwen3가 {abs(diff)}개 더 효율적\")\n    else:\n        print(f\"→ 동일\")\n\n    # Special tokens 비교\nprint(\"\\n\" + \"=\" * 80)\nprint(\"4. Special Tokens 비교\")\nprint(\"=\" * 80)\n\nprint(f\"\\n[Qwen3 Special Tokens]\")\nfor token_name in ['bos_token', 'eos_token', 'unk_token', 'pad_token']:\n    token = getattr(qwen, token_name, None)\n    if token:\n        token_id = getattr(qwen, f\"{token_name}_id\", None)\n        print(f\"  {token_name}: '{token}' (ID: {token_id})\")\n\nprint(f\"\\n[EXAONE Special Tokens]\")\nfor token_name in ['bos_token', 'eos_token', 'unk_token', 'pad_token']:\n    token = getattr(exaone, token_name, None)\n    if token:\n        token_id = getattr(exaone, f\"{token_name}_id\", None)\n        print(f\"  {token_name}: '{token}' (ID: {token_id})\")"}, {"number": 12, "code_number": null, "type": "markdown", "source": "## Hugging Face 모델 파일 구조 설명\n\nHugging Face Hub에 업로드된 파일들은 **Transformer 기반 언어 모델(LLM)**을 구성하는 핵심 요소들입니다. 크게 **설계도(Config)**, **가중치(Weights)**, **토크나이저(Tokenizer)** 세 그룹으로 나뉩니다.\n\n---\n\n### 1. 모델 아키텍처 및 설정 (설계도)\n\n* **`config.json`**\n    * **의미:** 모델의 **구조와 설계도**가 담긴 가장 중요한 설정 파일입니다.\n    * **내용:** 모델의 종류(Llama, BERT 등), 레이어(Layer) 수, 히든 사이즈, 어텐션 헤드 수 등을 정의하여 빈 모델(Skeleton)을 만듭니다.\n\n* **`generation_config.json`**\n    * **의미:** 텍스트 **생성(Generation) 시 사용할 기본 옵션** 파일입니다.\n    * **내용:** `max_length`(최대 길이), `temperature`(창의성), `top_p`, `eos_token_id`(종료 토큰) 등의 기본 설정값이 들어있습니다.\n\n### 2. 모델 가중치 (학습된 뇌)\n\n* **`model.safetensors`**\n    * **의미:** 실제 **학습된 파라미터(가중치)**가 저장된 파일입니다. (가장 용량이 큼)\n    * **특징:**\n        * 기존 PyTorch의 `.bin` 파일보다 로딩 속도가 빠릅니다.\n        * 보안 취약점(악성 코드 실행 등)을 해결한 안전한 형식입니다.\n\n### 3. 토크나이저 (언어 처리기)\n사람의 언어(Text)를 모델이 이해하는 숫자(Token ID)로 변환하는 규칙들입니다.\n\n* **`vocab.json`**\n    * **의미:** **단어장(Vocabulary)** 파일입니다. 단어와 그에 대응하는 숫자 ID가 매핑되어 있습니다.\n* **`merges.txt`**\n    * **의미:** **BPE 병합 규칙** 파일입니다. 알파벳 조각들이 어떻게 합쳐져서 단어가 되는지 정의합니다.\n* **`tokenizer.json`**\n    * **의미:** `vocab.json`과 `merges.txt` 등을 하나로 통합하여 최적화한 파일로, 로딩 속도가 매우 빠릅니다.\n* **`tokenizer_config.json`**\n    * **의미:** 토크나이저 설정 파일입니다. 어떤 클래스를 쓸지, 특수 토큰(`<s>`, `<pad>` 등)은 무엇인지 정의합니다.\n\n---\n\n### 요약\n\n| 파일명 | 비유 | 역할 |\n| :--- | :--- | :--- |\n| `config.json` | **설계도** | 모델 구조 정의 |\n| `model.safetensors` | **뇌** | 학습된 지식(가중치) 저장 |\n| `tokenizer.json` | **번역기** | 텍스트 ↔ 숫자 변환 |\n| `generation_config.json` | **말하기 습관** | 생성 옵션 설정 |"}, {"number": 13, "code_number": null, "type": "markdown", "source": "## Simulation\nhttps://tiktokenizer.vercel.app/?model=cl100k_base"}], "blanks": [{"id": "blank-token-encode", "label": "문자열을 token ID로 인코딩", "answer": "encode"}, {"id": "blank-token-decode", "label": "token ID를 문자열로 디코딩", "answer": "decode"}, {"id": "blank-next-token-start", "label": "next-token 시작 인덱스", "answer": "1"}, {"id": "blank-next-token-end", "label": "next-token 끝 인덱스 보정", "answer": "1"}, {"id": "blank-input-start", "label": "입력 윈도우 시작 인덱스", "answer": "i"}, {"id": "blank-input-end", "label": "입력 윈도우 끝 인덱스 기준", "answer": "i"}, {"id": "blank-target-start-i", "label": "target 시작 위치 기준", "answer": "i"}, {"id": "blank-target-start-offset", "label": "target 시작 한 칸 이동", "answer": "1"}, {"id": "blank-target-end-i", "label": "target 끝 위치 기준", "answer": "i"}, {"id": "blank-target-end-offset", "label": "target 끝 한 칸 보정", "answer": "1"}, {"id": "blank-dataloader-dataset", "label": "DataLoader에 전달할 Dataset", "answer": "dataset"}, {"id": "blank-embedding-vocab", "label": "Embedding vocab_size", "answer": "vocab_size"}, {"id": "blank-embedding-dim", "label": "Embedding output_dim", "answer": "output_dim"}, {"id": "blank-embedding-input", "label": "Embedding 입력 token ID", "answer": "input_ids"}, {"id": "blank-input-embeddings", "label": "GPT 입력 임베딩 합산", "answer": "token_embeddings + pos_embeddings"}]}, "Chapter_3_Excercise_Attention.ipynb": {"page": "llm_chapter_3_subjective_test", "cells": [{"number": 1, "code_number": 1, "type": "code", "source": "### 중요: 이 코드는 인과적 어텐션 메커니즘을 구현한 PyTorch 모듈입니다.\nimport torch\nimport torch.nn as nn\n\nclass CausalAttention(nn.Module):\n    def __init__(self, d_in, d_out, context_length, dropout, qkv_bias=False):\n        \"\"\"\n        Args:\n            d_in: 입력 벡터의 차원 크기\n            d_out: 출력(및 쿼리/키/밸류) 벡터의 차원 크기\n            context_length: 모델이 한 번에 처리할 수 있는 최대 문맥 길이 (토큰 수)\n            dropout: 드롭아웃 확률\n            qkv_bias: 선형 레이어에 편향(bias)을 사용할지 여부\n        \"\"\"\n        super().__init__()\n        \n        # 1. 쿼리(Query), 키(Key), 밸류(Value)를 만들기 위한 선형 투영 레이어 정의\n        # 입력 벡터(d_in)를 각각의 목적에 맞는 벡터(d_out)로 변환합니다.\n        # TODO: Q/K/V 투영 레이어 타입과 인자를 채우세요.\n        # 힌트: 입력 d_in, 출력 d_out을 사용하는 Linear 레이어를 선언하세요.\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\n        self.W_key   = nn.Linear(d_in, d_out, bias=qkv_bias)\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\n\n        # 2. 과적합(Overfitting) 방지를 위한 드롭아웃 설정\n        self.dropout = nn.Dropout(dropout)\n\n        # 3. 인과적 마스크(Causal Mask) 생성 및 버퍼 등록\n        # 'register_buffer'를 사용하면 역전파(학습) 대상은 아니지만, 모델의 상태(state_dict)로 저장됩니다.\n        # torch.triu(..., diagonal=1): 대각선(0) 위쪽 삼각형 부분만 1로 채웁니다.\n        # 즉, '미래의 정보' 위치에 1을 표시하여 나중에 가릴(masking) 준비를 합니다.\n        self.register_buffer(\n            'mask', \n            torch.triu(torch.ones(context_length, context_length), diagonal=1)\n        )\n\n    def forward(self, x):\n        # x.shape: [배치 크기(b), 토큰 개수(num_tokens), 입력 차원(d_in)]\n        b, num_tokens, d_in = x.shape \n\n        # 입력 x를 통과시켜 현재 시점의 관심사(Query), 검색 대상(Key), 정보 내용(Value)을 추출합니다.\n        # region [Q, K, V 벡터 계산]\n        # TODO: Q, K, V 계산 호출 대상을 채우세요.\n        # 힌트: W_query, W_key, W_value를 각각 x에 적용하면 됩니다.\n        keys = [[BLANK:blank-key]]        # Shape: [b, num_tokens, d_out]\n        queries = self.W_query(x)   # Shape: [b, num_tokens, d_out]\n        values = self.W_value(x)    # Shape: [b, num_tokens, d_out]\n        # endregion\n\n        # Query와 Key의 내적(Dot Product)을 통해 각 토큰 간의 관련성을 구합니다.\n        # keys.transpose(1, 2): 행렬 곱을 위해 차원을 뒤집습니다. (d_out 차원끼리 곱해짐)\n        # region [어텐션 스코어(유사도) 계산]\n        # TODO: 어텐션 스코어 행렬곱 피연산자를 채우세요.\n        # 힌트: queries와 keys.transpose(1, 2)를 곱해 유사도 점수를 구합니다.\n        attn_scores = [[BLANK:blank-score]] \n        #endregion\n\n        # mask가 1인 위치(미래 시점의 토큰들)를 -무한대(-inf)로 채웁니다.\n        # 이렇게 하면 나중에 Softmax를 거칠 때 확률이 0이 되어, 미래 정보를 참조하지 못하게 됩니다.\n        # [:num_tokens, :num_tokens]: 입력 길이가 context_length보다 짧을 때를 대비해 크기를 맞춥니다.\n        # region [인과적 마스킹 (Masking) - 미래 정보 차단]\n        # TODO: 미래 시점의 어텐션 스코어를 가릴 값을 채우세요.\n        # 힌트: Softmax를 통과하면 0이 되도록 마이너스 무한대(-torch.inf)를 입력하세요.\n        attn_scores.masked_fill_(\n            self.mask.bool()[:num_tokens, :num_tokens], \n            -torch.inf\n        ) \n        # endregion\n\n        # 스케일링(/ keys.shape[-1]**0.5): 차원이 커질수록 내적 값이 커져 기울기 소실이 오는 것을 방지합니다.\n        # Softmax: 점수를 확률(0~1 사이, 합은 1)로 변환합니다.\n        # region [어텐션 가중치(Weights) 계산 및 스케일링]\n        # TODO: 어텐션 가중치 함수명을 채우세요.\n        # 힌트: 스케일 적용 후 softmax를 사용해 확률로 변환하세요.\n        attn_weights = torch.softmax(\n            attn_scores / keys.shape[-1]**0.5, dim=-1\n        )\n        # endregion\n\n        # 계산된 가중치 중 일부를 무작위로 0으로 만들어 모델이 특정 토큰에만 의존하는 것을 막습니다.\n        # region [드롭아웃 적용]\n        attn_weights = self.dropout(attn_weights)\n        # endregion \n\n        # 어텐션 가중치(확률)를 기반으로 Value(정보)들을 가중 합산합니다.\n        # 결과적으로 \"현재 토큰과 관련이 깊은 과거 토큰들의 정보\"가 진하게 섞인 벡터가 됩니다.\n        # region [문맥 벡터(Context Vector) 생성]\n        # TODO: 컨텍스트 벡터 계산 피연산자를 채우세요.\n        # 힌트: attn_weights와 values를 곱해 최종 컨텍스트 벡터를 얻습니다.\n        context_vec = [[BLANK:blank-context]]\n        # endregion\n        \n        return context_vec"}, {"number": 2, "code_number": 2, "type": "code", "source": "import torch\n\ninputs = torch.tensor(\n  [[0.43, 0.15, 0.89], # Your     (x^1)\n   [0.55, 0.87, 0.66], # journey  (x^2)\n   [0.57, 0.85, 0.64], # starts   (x^3)\n   [0.22, 0.58, 0.33], # with     (x^4)\n   [0.77, 0.25, 0.10], # one      (x^5)\n   [0.05, 0.80, 0.55]] # step     (x^6)\n)\n\nd_in = inputs.shape[1]   # 입력 차원 (d=3)\nd_out = 2                # Q, K, V의 출력 차원 (d=2)\n\nbatch = torch.stack((inputs, inputs), dim=0)\n# --- 실행 예시 ---\ntorch.manual_seed(123)\n\n# 가정: batch 변수가 이미 정의되어 있다고 가정 (예: b=2, num_tokens=6, d_in=...)\n# context_length는 모델이 허용하는 최대 길이이므로, 현재 배치의 길이와 같거나 더 길게 설정합니다.\ncontext_length = batch.shape[1] \n\nprint(\"context_length:\", context_length)\n\n# TODO: 어텐션 모듈 호출 대상을 채우세요.\n# 힌트: 직전에 생성한 CausalAttention 인스턴스(ca)를 호출하면 됩니다.\nca = CausalAttention(d_in, d_out, context_length, 0.0)\ncontext_vecs = cabatch)\n\nprint(context_vecs)\nprint(\"context_vecs.shape:\", context_vecs.shape)"}, {"number": 3, "code_number": 3, "type": "code", "source": "class MultiHeadAttentionWrapper(nn.Module):\n\n    def __init__(self, d_in, d_out, context_length, dropout, num_heads, qkv_bias=False):\n        super().__init__()\n        self.heads = nn.ModuleList(\n            [CausalAttention(d_in, d_out, context_length, dropout, qkv_bias) \n             for _ in range(num_heads)]\n        )\n\n    def forward(self, x):\n        return torch.cat([head(x) for head in self.heads], dim=-1)\n\n\ntorch.manual_seed(123)\n\ncontext_length = batch.shape[1] # This is the number of tokens\nd_in, d_out = 3, 2\nmha = MultiHeadAttentionWrapper(\n    d_in, d_out, context_length, 0.0, num_heads=2\n)\n\ncontext_vecs = mha(batch)\n\nprint(context_vecs)\nprint(\"context_vecs.shape:\", context_vecs.shape)"}, {"number": 4, "code_number": 4, "type": "code", "source": "class MultiHeadAttention(nn.Module):\n    def __init__(self, d_in, d_out, context_length, dropout, num_heads, qkv_bias=False):\n        super().__init__()\n        assert (d_out % num_heads == 0), \\\n            \"d_out must be divisible by num_heads\"\n\n        self.d_out = d_out\n        self.num_heads = num_heads\n        self.head_dim = d_out // num_heads # Reduce the projection dim to match desired output dim\n\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\n        self.dropout = nn.Dropout(dropout)\n        self.register_buffer(\n            \"mask\",\n            torch.triu(torch.ones(context_length, context_length),\n                       diagonal=1)\n        )\n\n    def forward(self, x):\n        b, num_tokens, d_in = x.shape\n        # As in `CausalAttention`, for inputs where `num_tokens` exceeds `context_length`, \n        # this will result in errors in the mask creation further below. \n        # In practice, this is not a problem since the LLM (chapters 4-7) ensures that inputs  \n        # do not exceed `context_length` before reaching this forward method.\n\n        keys = self.W_key(x) # Shape: (b, num_tokens, d_out)\n        queries = self.W_query(x)\n        values = self.W_value(x)\n\n        # We implicitly split the matrix by adding a `num_heads` dimension\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\n        keys = keys.view(b, num_tokens, self.num_heads, self.head_dim) \n        values = values.view(b, num_tokens, self.num_heads, self.head_dim)\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\n\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\n        keys = keys.transpose(1, 2)\n        queries = queries.transpose(1, 2)\n        values = values.transpose(1, 2)\n\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\n\n        # Original mask truncated to the number of tokens and converted to boolean\n        mask_bool = self.mask.bool()[:num_tokens, :num_tokens]\n\n        # Use the mask to fill attention scores\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\n        \n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\n        attn_weights = self.dropout(attn_weights)\n\n        # Shape: (b, num_tokens, num_heads, head_dim)\n        context_vec = (attn_weights @ values).transpose(1, 2) \n        \n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\n        context_vec = self.out_proj(context_vec) # optional projection\n\n        return context_vec\n\ntorch.manual_seed(123)\n\nbatch_size, context_length, d_in = batch.shape\nd_out = 2\nmha = MultiHeadAttention(d_in, d_out, context_length, 0.0, num_heads=2)\n\ncontext_vecs = mha(batch)\n\nprint(context_vecs)\nprint(\"context_vecs.shape:\", context_vecs.shape)"}, {"number": 5, "code_number": null, "type": "markdown", "source": "<img src=\"llm_from_scratch/images/llm_from_scratch/ch03_compressed/26.webp\" width=\"600px\">"}, {"number": 6, "code_number": null, "type": "markdown", "source": "## Simulation\n- https://poloclub.github.io/transformer-explainer/\n- https://bbycroft.net/llm"}, {"number": 7, "code_number": null, "type": "markdown", "source": ""}], "blanks": [{"id": "blank-key", "label": "Key 투영", "answer": "self.W_key(x)"}, {"id": "blank-score", "label": "Q·K 내적 점수", "answer": "queries @ keys.transpose(1, 2)"}, {"id": "blank-context", "label": "Value 가중합", "answer": "attn_weights @ values"}]}, "Chapter_4_Excercise_GPT.ipynb": {"page": "llm_chapter_4_subjective_test", "cells": [{"number": 1, "code_number": 1, "type": "code", "source": "import tiktoken\nimport torch\nimport torch.nn as nn\nfrom torch.utils.data import Dataset, DataLoader\n\n#####################################\n# Chapter 2: 데이터 로딩 및 처리\n#####################################\n\nclass GPTDatasetV1(Dataset):\n    \"\"\"\n    GPT 학습을 위한 데이터셋 클래스입니다.\n    텍스트를 입력받아 토큰화하고, 입력(input)과 타겟(target) 쌍을 만듭니다.\n    \"\"\"\n    def __init__(self, txt, tokenizer, max_length, stride):\n        self.input_ids = []\n        self.target_ids = []\n\n        # 1. 전체 텍스트를 토큰화합니다.\n        # <|endoftext|> 같은 특수 토큰도 허용하여 인코딩합니다.\n        token_ids = tokenizer.encode(txt, allowed_special={\"<|endoftext|>\"})\n\n        # 2. 슬라이딩 윈도우 방식으로 데이터를 조각냅니다.\n        # stride만큼 이동하면서 max_length 길이의 덩어리(chunk)를 만듭니다.\n        for i in range(0, len(token_ids) - max_length, stride):\n            input_chunk = token_ids[i:i + max_length]\n            # 타겟은 입력보다 한 칸 뒤의 토큰들입니다 (다음 토큰 예측 과제).\n            target_chunk = token_ids[i + 1: i + max_length + 1]\n            \n            # 텐서로 변환하여 저장\n            self.input_ids.append(torch.tensor(input_chunk))\n            self.target_ids.append(torch.tensor(target_chunk))\n\n    def __len__(self):\n        # 데이터셋의 총 샘플 수 반환\n        return len(self.input_ids)\n\n    def __getitem__(self, idx):\n        # 특정 인덱스의 입력과 타겟 쌍 반환\n        return self.input_ids[idx], self.target_ids[idx]\n\n\ndef create_dataloader_v1(txt, batch_size=4, max_length=256,\n                         stride=128, shuffle=True, drop_last=True, num_workers=0):\n    \"\"\"\n    텍스트 데이터를 받아 학습에 사용할 DataLoader를 생성하는 함수입니다.\n    \"\"\"\n    # 토크나이저 초기화 (GPT-2용 BPE 인코딩 사용)\n    tokenizer = tiktoken.get_encoding(\"gpt2\")\n\n    # 데이터셋 생성\n    dataset = GPTDatasetV1(txt, tokenizer, max_length, stride)\n\n    # 데이터로더 생성 (배치 단위로 데이터를 묶어주고 셔플링 수행)\n    dataloader = DataLoader(\n        dataset, batch_size=batch_size, shuffle=shuffle, drop_last=drop_last, num_workers=num_workers)\n\n    return dataloader"}, {"number": 2, "code_number": 2, "type": "code", "source": "\n#####################################\n# Chapter 3: 어텐션 메커니즘 (모델의 핵심)\n#####################################\nclass MultiHeadAttention(nn.Module):\n    \"\"\"\n    멀티 헤드 셀프 어텐션 (Multi-Head Self-Attention) 모듈입니다.\n    입력 데이터 간의 관계성을 여러 관점(Head)에서 병렬로 학습합니다.\n    \"\"\"\n    def __init__(self, d_in, d_out, context_length, dropout, num_heads, qkv_bias=False):\n        super().__init__()\n        assert d_out % num_heads == 0, \"출력 차원(d_out)은 헤드 수(num_heads)로 나누어 떨어져야 합니다.\"\n\n        self.d_out = d_out\n        self.num_heads = num_heads\n        self.head_dim = d_out // num_heads  # 각 헤드가 담당할 차원 크기\n\n        # Query, Key, Value를 만들기 위한 선형 투영 레이어들\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\n        \n        # 멀티 헤드 결과를 하나로 합친 후 통과시키는 출력 레이어\n        self.out_proj = nn.Linear(d_out, d_out) \n        self.dropout = nn.Dropout(dropout)\n        \n        # Causal Mask (인과적 마스킹) 생성: 미래의 토큰을 보지 못하게 함\n        # 상삼각 행렬(대각선 위쪽)을 1로 채워서 나중에 마스킹에 사용\n        self.register_buffer(\"mask\", torch.triu(torch.ones(context_length, context_length), diagonal=1))\n\n    def forward(self, x):\n        b, num_tokens, d_in = x.shape # b: 배치 크기, num_tokens: 시퀀스 길이\n\n        # 1. Q, K, V 계산\n        keys = self.W_key(x)     # Shape: (b, num_tokens, d_out)\n        queries = self.W_query(x)\n        values = self.W_value(x)\n\n        # 2. 헤드 나누기 (Multi-head splitting)\n        # 차원을 변형하여 여러 헤드가 병렬로 처리할 수 있게 함\n        # (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\n        keys = keys.view(b, num_tokens, self.num_heads, self.head_dim)\n        values = values.view(b, num_tokens, self.num_heads, self.head_dim)\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\n\n        # 3. 차원 순서 변경 (Transpose)\n        # (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\n        # 이렇게 하면 (num_tokens, head_dim) 행렬이 헤드 개수만큼 독립적으로 존재하게 됨\n        keys = keys.transpose(1, 2)\n        queries = queries.transpose(1, 2)\n        values = values.transpose(1, 2)\n\n        # 4. Scaled Dot-Product Attention 계산\n        # Query와 Key의 내적 (유사도 계산)\n        attn_scores = queries @ keys.transpose(2, 3)  # 결과 Shape: (b, num_heads, num_tokens, num_tokens)\n\n        # 5. 마스킹 (Masking)\n        # 현재 시점보다 미래의 토큰 정보를 참조하지 못하게 -inf로 가림\n        mask_bool = self.mask.bool()[:num_tokens, :num_tokens]\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\n\n        # 6. 소프트맥스 및 드롭아웃\n        # 점수를 확률로 변환 (합이 1이 되도록)\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\n        attn_weights = self.dropout(attn_weights)\n\n        # 7. Value와의 가중치 합 (Context Vector 계산)\n        # Shape: (b, num_heads, num_tokens, head_dim)\n        context_vec = (attn_weights @ values).transpose(1, 2) \n\n        # 8. 헤드 결합 (Concatenation)\n        # 나눠졌던 헤드들을 다시 원래의 d_out 차원으로 합침\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\n        \n        # 9. 최종 선형 투영\n        context_vec = self.out_proj(context_vec) \n\n        return context_vec"}, {"number": 3, "code_number": 3, "type": "code", "source": "\n#####################################\n# Chapter 4: GPT 아키텍처 구성 요소\n#####################################\nclass LayerNorm(nn.Module):\n    \"\"\"\n    층 정규화 (Layer Normalization): 학습 안정성을 높임\n    \"\"\"\n    def __init__(self, emb_dim):\n        super().__init__()\n        self.eps = 1e-5\n        self.scale = nn.Parameter(torch.ones(emb_dim)) # 학습 가능한 스케일 파라미터 (Gamma)\n        self.shift = nn.Parameter(torch.zeros(emb_dim)) # 학습 가능한 시프트 파라미터 (Beta)\n\n    def forward(self, x):\n        mean = x.mean(dim=-1, keepdim=True)\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\n        # TODO: LayerNorm 계산식의 통계량 변수를 채우세요.\n        # 힌트: 평균(mean)과 분산(var)을 사용해 정규화합니다.\n        norm_x = [[BLANK:blank-layernorm]]\n        # TODO: LayerNorm 학습 파라미터를 채우세요.\n        # 힌트: scale로 곱하고 shift를 더하는 형태를 사용합니다.\n        return self.scale * norm_x + self.shift\n\n\nclass GELU(nn.Module):\n    \"\"\"\n    GELU 활성화 함수: GPT 계열에서 주로 사용하는 비선형 함수\n    \"\"\"\n    def __init__(self):\n        super().__init__()\n\n    def forward(self, x):\n        return 0.5 * x * (1 + torch.tanh(\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\n            (x + 0.044715 * torch.pow(x, 3))\n        ))\n\n\nclass FeedForward(nn.Module):\n    \"\"\"\n    피드 포워드 네트워크 (Feed-Forward Network)\n    어텐션이 모은 정보를 각 토큰별로 개별적으로 가공하는 역할\n    보통 임베딩 차원을 4배로 늘렸다가 다시 줄임\n    \"\"\"\n    def __init__(self, cfg):\n        super().__init__()\n        # TODO: FeedForward의 확장 배수와 활성화 함수 클래스를 채우세요.\n        # 힌트: GPT 구조에서는 hidden 크기를 4배로 확장합니다. 확장 Linear와 축소 Linear 사이에 GELU 활성화 함수를 넣으세요.\n        self.layers = nn.Sequential(\n            nn.Linear(cfg[\"emb_dim\"], 4 * cfg[\"emb_dim\"]),\n            GELU(),\n            nn.Linear(4 * cfg[\"emb_dim\"], cfg[\"emb_dim\"]),\n        )\n\n    def forward(self, x):\n        return self.layers(x)"}, {"number": 4, "code_number": 4, "type": "code", "source": "##중요 : 아래는 GPT 모델 전체 구조를 정의하는 코드입니다\n\n#####################################\n# Chapter 4: GPT 아키텍처 조립\n#####################################\nclass TransformerBlock(nn.Module):\n    \"\"\"\n    표준 트랜스포머 블록 (Decoder Block)\n    구조: LayerNorm -> Attention -> Add(Residual) -> LayerNorm -> FeedForward -> Add(Residual)\n    \"\"\"\n    def __init__(self, cfg):\n        super().__init__()\n        self.att = MultiHeadAttention(\n            d_in=cfg[\"emb_dim\"],\n            d_out=cfg[\"emb_dim\"],\n            context_length=cfg[\"context_length\"],\n            num_heads=cfg[\"n_heads\"],\n            dropout=cfg[\"drop_rate\"],\n            qkv_bias=cfg[\"qkv_bias\"])\n        self.ff = FeedForward(cfg)\n        self.norm1 = LayerNorm(cfg[\"emb_dim\"])\n        self.norm2 = LayerNorm(cfg[\"emb_dim\"])\n        self.drop_shortcut = nn.Dropout(cfg[\"drop_rate\"])\n\n    def forward(self, x):\n        # region [어텐션 블록 (Residual Connection 적용)]\n        shortcut = x\n        x = self.norm1(x) # Pre-LayerNorm 방식\n        # TODO\n        x = self.att(x)   \n        x = self.drop_shortcut(x)\n        x = x + shortcut  # 원본 입력을 더해줌 (기울기 소실 방지)\n        # endregion\n\n        # region [피드 포워드 블록 (Residual Connection 적용)]\n        shortcut = x\n        x = self.norm2(x)\n        # TODO\n        x = self.ff(x)\n        x = self.drop_shortcut(x)\n        x = x + shortcut  # 원본 입력 다시 더함\n        # endregion\n\n        return x\nclass GPTModel(nn.Module):\n    \"\"\"\n    전체 GPT 모델 구조 정의\n    Embedding -> Transformer Blocks -> Final Norm -> Output Head\n    \"\"\"\n    def __init__(self, cfg):\n        super().__init__()\n        # 토큰 임베딩 (단어 -> 벡터)\n        # TODO\n        self.tok_emb = nn.Embedding(cfg[\"vocab_size\"], cfg[\"emb_dim\"])\n        # 위치 임베딩 (위치 정보 -> 벡터)\n        # TODO \n        self.pos_emb = [[BLANK:blank-pos-embedding]]\n        self.drop_emb = nn.Dropout(cfg[\"drop_rate\"])\n\n        # 트랜스포머 블록 쌓기 (n_layers 만큼)\n        self.trf_blocks = nn.Sequential(\n            *[TransformerBlock(cfg) for _ in range(cfg[\"n_layers\"])])\n\n        # 최종 정규화 및 출력 헤드\n        self.final_norm = LayerNorm(cfg[\"emb_dim\"])\n        # TODO\n        self.out_head = [[BLANK:blank-output-head]]\n\n    def forward(self, in_idx):\n        batch_size, seq_len = in_idx.shape\n        \n        # region [임베딩 생성]\n        tok_embeds = self.tok_emb(in_idx)\n        pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\n        # endregion\n\n        # region [토큰 임베딩과 위치 임베딩 합산]\n        # TODOe\n        x = tok_embeds + pos_embeds\n        # endregion\n\n        x = self.drop_emb(x)\n        \n        # region [트랜스포머 블록 통과]\n        # TODO\n        x = self.trf_blocks(x)\n        # endregion\n\n        # region [최종 출력 계산]\n        x = self.final_norm(x)\n        # TODO\n        logits = self.out_head(x) # 각 단어에 대한 예측 점수 (Logits)\n        # endregion\n        \n        return logits"}, {"number": 5, "code_number": 5, "type": "code", "source": "\ndef generate_text_simple(model, idx, max_new_tokens, context_size):\n    \"\"\"\n    간단한 텍스트 생성 루프\n    현재 문맥을 넣어 다음 토큰을 예측하고, 이를 다시 문맥에 추가하여 반복함\n    \"\"\"\n    # idx: 현재 문맥의 토큰 인덱스들 (Batch, Time)\n    for _ in range(max_new_tokens):\n\n        # 모델이 지원하는 최대 길이(context_size)를 넘지 않도록 자름\n        idx_cond = idx[:, -context_size:]\n\n        # 모델 예측 (기울기 계산 불필요)\n        # TODO\n        with torch.no_grad():\n            logits = model(idx_cond)\n\n        # 마지막 타임스텝의 예측값만 가져옴 (다음 단어 예측이므로)\n        # (batch, n_token, vocab_size) -> (batch, vocab_size)\n        # TODO\n        logits = logits[:, -1, :]\n\n        # 가장 확률(로짓값)이 높은 토큰 선택 (Greedy Decoding)\n        # TODO\n        idx_next = torch.argmax(logits, dim=-1, keepdim=True) \n\n        # 예측된 토큰을 현재 시퀀스 뒤에 이어 붙임\n        # TODO\n        idx = torch.cat((idx, idx_next), dim=1) \n\n    return idx"}, {"number": 6, "code_number": 6, "type": "code", "source": "def main():\n    # GPT-2 Small 모델 설정값 (124M 파라미터)\n    GPT_CONFIG_124M = {\n        \"vocab_size\": 50257,     # 단어 집합 크기\n        \"context_length\": 1024,  # 최대 문맥 길이\n        \"emb_dim\": 768,          # 임베딩 차원\n        \"n_heads\": 12,           # 어텐션 헤드 수\n        \"n_layers\": 12,          # 레이어 수\n        \"drop_rate\": 0.1,        # 드롭아웃 비율\n        \"qkv_bias\": False        # Q,K,V 편향 사용 여부\n    }\n\n    torch.manual_seed(123)\n    \n    # 모델 초기화 및 평가 모드 설정 (드롭아웃 비활성화)\n    model = GPTModel(GPT_CONFIG_124M)\n    model.eval()\n\n    start_context = \"Hello, I am\"\n\n    # 입력 텍스트 인코딩\n    tokenizer = tiktoken.get_encoding(\"gpt2\")\n    encoded = tokenizer.encode(start_context)\n    encoded_tensor = torch.tensor(encoded).unsqueeze(0) # 배치 차원 추가\n\n    print(f\"\\n{50*'='}\\n{22*' '}IN\\n{50*'='}\")\n    print(\"\\nInput text:\", start_context)\n    print(\"Encoded input text:\", encoded)\n    print(\"encoded_tensor.shape:\", encoded_tensor.shape)\n\n    # 텍스트 생성 실행\n    out = generate_text_simple(\n        model=model,\n        idx=encoded_tensor,\n        max_new_tokens=10,  # 10개의 새로운 토큰 생성\n        context_size=GPT_CONFIG_124M[\"context_length\"]\n    )\n    \n    # 생성된 결과 디코딩\n    decoded_text = tokenizer.decode(out.squeeze(0).tolist())\n\n    print(f\"\\n\\n{50*'='}\\n{22*' '}OUT\\n{50*'='}\")\n    print(\"\\nOutput:\", out)\n    print(\"Output length:\", len(out[0]))\n    print(\"Output text:\", decoded_text)\n\nif __name__ == \"__main__\":\n    main()"}, {"number": 7, "code_number": 7, "type": "code", "source": ""}], "blanks": [{"id": "blank-layernorm", "label": "LayerNorm 정규화식", "answer": "(x - mean) / torch.sqrt(var + self.eps)"}, {"id": "blank-pos-embedding", "label": "위치 임베딩 레이어", "answer": "nn.Embedding(cfg[\"context_length\"], cfg[\"emb_dim\"])"}, {"id": "blank-output-head", "label": "Vocabulary 출력 Head", "answer": "nn.Linear(cfg[\"emb_dim\"], cfg[\"vocab_size\"], bias=False)"}]}, "Chapter_5_Excercise_Pretraining.ipynb": {"page": "llm_chapter_5_subjective_test", "cells": [{"number": 1, "code_number": 1, "type": "code", "source": "# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\n# Source for \"Build a Large Language Model From Scratch\"\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\n# Code: https://github.com/rasbt/LLMs-from-scratch\n\nimport matplotlib.pyplot as plt\nimport os\nimport requests\nimport torch\nimport tiktoken\n\nfrom previous_chapters import GPTModel, create_dataloader_v1, generate_text_simple"}, {"number": 2, "code_number": 2, "type": "code", "source": "### 중요: lOSS를 계산합니다.\ndef calc_loss_batch(input_batch, target_batch, model, device):\n    \"\"\"\n    하나의 배치(Batch)에 대해 모델의 예측값과 실제값 사이의 오차(Loss)를 계산합니다.\n    \"\"\"\n    # 데이터를 GPU(또는 설정된 device)로 이동\n    input_batch, target_batch = input_batch.to(device), target_batch.to(device)\n    \n    # 1. 모델의 순전파(Forward Pass)\n    # logits shape: (batch_size, sequence_length, vocab_size)\n    logits = model(input_batch)\n    \n    # 2. 손실 계산 (CrossEntropyLoss)\n    # PyTorch의 CrossEntropyLoss는 입력을 (N, C) 형태로 받기를 원합니다.\n    #   - N: 전체 샘플 수 (여기서는 Batch_size * Sequence_length)\n    #   - C: 클래스 수 (여기서는 Vocab_size)\n    # 따라서 3차원 텐서를 2차원으로 평탄화(flatten) 해야 합니다.\n    \n    # logits.flatten(0, 1) -> (batch_size * sequence_length, vocab_size)\n    # target_batch.flatten() -> (batch_size * sequence_length)\n    # region [손실 계산 (CrossEntropyLoss)]\n    # TODO: 손실 함수명과 logits/target 평탄화 메서드를 채우세요.\n    # 힌트: cross_entropy에 logits.flatten(0, 1)과 target_batch.flatten()을 전달합니다.\n    loss = [[BLANK:blank-cross-entropy]]\n    # endregion\n    return loss"}, {"number": 3, "code_number": 3, "type": "code", "source": "### 중요: 모델을 학습합니다.\ndef train_model_simple(model, train_loader, val_loader, optimizer, device, num_epochs,\n                       eval_freq, eval_iter, start_context, tokenizer):\n    \"\"\"\n    [핵심] 모델 훈련을 담당하는 메인 루프입니다.\n    \"\"\"\n    # 로그 저장을 위한 리스트들\n    train_losses, val_losses, track_tokens_seen = [], [], []\n    tokens_seen = 0\n    global_step = -1\n\n    # Epoch: 전체 데이터셋을 한 번 훑는 단위\n    for epoch in range(num_epochs):\n        # region [train 모드 설정]\n        # TODO: 모델 모드 전환 메서드를 채우세요.\n        # 힌트: 학습 루프 시작 전에는 train 모드를 설정해야 합니다.\n        model.train()  # 훈련 시작 전 반드시 train 모드 설정\n        # endregion\n        \n        for input_batch, target_batch in train_loader:\n            # [Step 1] 이전 배치에서 계산된 기울기 초기화 (필수)\n            # region [기울기 초기화]\n            # TODO: 기울기 초기화 메서드를 채우세요.\n            # 힌트: 배치마다 이전 gradient가 누적되지 않도록 zero_grad()를 먼저 호출합니다.\n            [[BLANK:blank-zero-grad]]\n            # endregion\n            #              \n            # [Step 2] 순전파 및 손실 계산\n            # region [손실 계산]\n            # TODO: 배치 손실 계산 함수명을 채우세요.\n            # 힌트: input_batch, target_batch, model, device를 인자로 받는 헬퍼를 호출하면 됩니다.\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\n            # endregion\n\n            # [Step 3] 역전파 (Backpropagation): 각 파라미터별 기울기(Gradient) 계산\n            # region [역전파 수행]\n            # TODO: 역전파 메서드를 채우세요.\n            # 힌트: loss 텐서에서 backward()를 호출해 gradient를 계산합니다.\n            [[BLANK:blank-backward]] \n            # endregion\n\n            # [Step 4] 가중치 업데이트: 계산된 기울기를 이용해 파라미터 수정\n            # region [가중치 업데이트]\n            # TODO: 파라미터 업데이트 메서드를 채우세요.\n            # 힌트: backward()로 계산된 gradient를 이용해 [[BLANK:blank-step]]으로 가중치를 갱신합니다.\n            optimizer.step()   \n            # endregion\n            \n            tokens_seen += input_batch.numel() # 처리한 토큰 수 카운트\n            global_step += 1\n\n            # 일정 스텝마다 검증(Evaluation) 수행 및 로그 출력\n            if global_step % eval_freq == 0:\n                train_loss, val_loss = evaluate_model(\n                    model, train_loader, val_loader, device, eval_iter)\n                train_losses.append(train_loss)\n                val_losses.append(val_loss)\n                track_tokens_seen.append(tokens_seen)\n                print(f\"Ep {epoch+1} (Step {global_step:06d}): \"\n                      f\"Train loss {train_loss:.3f}, Val loss {val_loss:.3f}\")\n\n        # 한 에포크가 끝날 때마다 샘플 문장을 생성하여 모델이 똑똑해지고 있는지 확인\n        generate_and_print_sample(\n            model, tokenizer, device, start_context\n        )\n\n    return train_losses, val_losses, track_tokens_seen"}, {"number": 4, "code_number": 4, "type": "code", "source": "### 중요: 결과를 생성합니다.\ndef generate(model, idx, max_new_tokens, context_size, eos_id=None):\n    \"\"\"\n    고급 텍스트 생성 함수입니다. (Top-k 샘플링 & Temperature Scaling 포함)\n    \n    Args:\n        idx: 현재 문맥 (Shape: Batch, Time)\n        temperature: 0이면 결정적(Greedy), 높을수록 창의적/랜덤\n        top_k: 확률 상위 k개만 후보로 남김 (이상한 단어 생성 방지)\n    \"\"\"\n\n    # 지정된 토큰 수만큼 반복 생성\n    for _ in range(max_new_tokens):\n        \n        # 1. 문맥 자르기 (Context Cropping)\n        # 모델이 처리할 수 있는 최대 길이(context_size)를 넘지 않도록 뒤쪽만 남김\n        idx_cond = idx[:, -context_size:]\n        \n        # 2. 모델 예측\n        # region [모델 예측]\n        with torch.no_grad():\n            logits = model(idx_cond)\n        # endregion\n\n        # 3. 다음 단어 예측을 위해 '마지막 시점'의 로짓만 추출\n        # logits shape: (batch, seq_len, vocab_size) -> (batch, vocab_size)\n        # region [마지막 시점 로짓 추출]\n        # TODO: 마지막 시점 선택 인덱스를 채우세요.\n        # 힌트: 다음 토큰 생성은 마지막 위치 logits만 사용합니다.\n        logits = logits[:, -1, :]\n        # endregion\n\n        # 가장 높은 확률을 가진 토큰 선택 (Greedy Decoding)\n        # region [다음 토큰 선택 (Greedy Decoding)]\n        # TODO: 다음 토큰 선택 함수명을 채우세요.\n        # 힌트: Greedy decoding에서는 argmax를 사용합니다.\n        idx_next = torch.argmax(logits, dim=-1, keepdim=True)\n        # endregion\n\n        # 4. 종료 조건 확인 (EOS 토큰이 나오면 중단)\n        if idx_next == eos_id:\n            break\n\n        # 5. 생성된 토큰 이어붙이기\n        # 기존 문장(idx) 뒤에 새로 뽑은 토큰(idx_next)을 붙여 다음 스텝의 입력으로 씀\n        # region [생성된 토큰 이어붙이기]\n        # TODO: concat 대상 변수를 채우세요.\n        # 힌트: 방금 고른 idx_next를 기존 idx 뒤에 붙입니다.\n        idx = torch.cat((idx, idx_next), dim=1)\n        # endregion\n        \n    return idx"}, {"number": 5, "code_number": 5, "type": "code", "source": "def text_to_token_ids(text, tokenizer):\n    \"\"\"\n    사람이 읽는 텍스트 문자열을 모델이 이해하는 토큰 ID 텐서로 변환합니다.\n    \"\"\"\n    encoded = tokenizer.encode(text)\n    \n    # 모델은 입력으로 (Batch_Size, Sequence_Length)의 2차원 텐서를 요구합니다.\n    # 하지만 여기서는 문장 1개이므로 Batch_Size가 없습니다.\n    # 따라서 .unsqueeze(0)를 사용하여 가짜 배치 차원을 추가합니다.\n    # 예: [12, 34, 56] -> [[12, 34, 56]] (Shape: [1, seq_len])\n    # TODO: 배치 차원 추가 메서드를 채우세요.\n    # 힌트: 단일 시퀀스를 모델 입력 형태로 만들기 위해 unsqueeze(0)를 사용합니다.\n    encoded_tensor = torch.tensor(encoded).unsqueeze(0) \n    return encoded_tensor\n\n\ndef token_ids_to_text(token_ids, tokenizer):\n    \"\"\"\n    모델이 뱉어낸 토큰 ID 텐서를 사람이 읽을 수 있는 텍스트로 변환합니다.\n    \"\"\"\n    # 디코딩을 위해 불필요한 배치 차원을 제거합니다.\n    # 예: [[12, 34, 56]] -> [12, 34, 56]\n    # TODO: 배치 차원 제거 메서드를 채우세요.\n    # 힌트: 디코딩 전에는 squeeze(0)로 앞쪽 차원을 제거합니다.\n    flat = token_ids.squeeze(0) \n    return tokenizer.decode(flat.tolist())\n\n\ndef calc_loss_loader(data_loader, model, device, num_batches=None):\n    \"\"\"\n    데이터 로더 전체(또는 일부)를 돌면서 평균 손실을 계산합니다.\n    훈련에는 관여하지 않고, 오직 '평가(Evaluation)' 목적으로만 쓰입니다.\n    \"\"\"\n    total_loss = 0.\n    if len(data_loader) == 0:\n        return float(\"nan\")\n    elif num_batches is None:\n        num_batches = len(data_loader)\n    else:\n        # 평가 시간을 단축하기 위해 전체 데이터를 다 보지 않고 일부만 볼 수 있게 설정\n        num_batches = min(num_batches, len(data_loader))\n        \n    for i, (input_batch, target_batch) in enumerate(data_loader):\n        if i < num_batches:\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\n            total_loss += loss.item() # 텐서에서 실수값(float)만 추출하여 누적\n        else:\n            break\n    return total_loss / num_batches\n\n\ndef evaluate_model(model, train_loader, val_loader, device, eval_iter):\n    \"\"\"\n    현재 모델의 성능을 훈련 세트와 검증 세트 각각에 대해 평가합니다.\n    \"\"\"\n    model.eval() # [중요] 평가 모드 전환: Dropout이나 BatchNorm 등의 동작이 변경됨\n    \n    with torch.no_grad(): # [중요] 기울기(Gradient) 계산 끔 -> 메모리 절약 및 속도 향상\n        train_loss = calc_loss_loader(train_loader, model, device, num_batches=eval_iter)\n        val_loss = calc_loss_loader(val_loader, model, device, num_batches=eval_iter)\n        \n    model.train() # 평가가 끝나면 다시 훈련 모드로 복귀해야 함\n    return train_loss, val_loss\n\n\ndef generate_and_print_sample(model, tokenizer, device, start_context):\n    \"\"\"\n    훈련 중간중간 모델이 문장을 어떻게 생성하는지 눈으로 확인하기 위한 함수입니다.\n    \"\"\"\n    model.eval() # 평가 모드\n    context_size = model.pos_emb.weight.shape[0] # 모델이 처리 가능한 최대 길이\n    encoded = text_to_token_ids(start_context, tokenizer).to(device)\n    \n    with torch.no_grad():\n        token_ids = generate_text_simple(\n            model=model, idx=encoded,\n            max_new_tokens=50, context_size=context_size\n        )\n        decoded_text = token_ids_to_text(token_ids, tokenizer)\n        \n        # 출력이 너무 길어지면 보기 힘드므로 줄바꿈을 공백으로 변경\n        print(decoded_text.replace(\"\\n\", \" \"))  \n    \n    model.train() # 훈련 모드 복귀\n\n\n\ndef plot_losses(epochs_seen, tokens_seen, train_losses, val_losses):\n    \"\"\"\n    훈련 진행 상황(Loss 변화)을 시각화하는 함수입니다.\n    X축을 'Epoch'와 '처리한 토큰 수' 두 가지 기준으로 보여줍니다.\n    \"\"\"\n    fig, ax1 = plt.subplots()\n\n    # 기본 X축: Epoch 기준\n    ax1.plot(epochs_seen, train_losses, label=\"Training loss\")\n    ax1.plot(epochs_seen, val_losses, linestyle=\"-.\", label=\"Validation loss\")\n    ax1.set_xlabel(\"Epochs\")\n    ax1.set_ylabel(\"Loss\")\n    ax1.legend(loc=\"upper right\")\n\n    # 보조 X축 (상단): 처리한 토큰 수(Tokens seen) 기준\n    ax2 = ax1.twiny() \n    ax2.plot(tokens_seen, train_losses, alpha=0) # 투명한 그래프로 축만 생성\n    ax2.set_xlabel(\"Tokens seen\")\n\n    fig.tight_layout() \n    # plt.show() # 주피터 노트북 환경이면 주석 해제\n\n\ndef main(gpt_config, settings):\n    # 랜덤 시드 고정 (실험 재현성을 위해)\n    torch.manual_seed(123)\n    device = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n\n    ##############################\n    # 1. 데이터 준비\n    ##############################\n    file_path = \"datas/the-verdict.txt\"\n    url = \"https://raw.githubusercontent.com/rasbt/LLMs-from-scratch/main/ch02/01_main-chapter-code/the-verdict.txt\"\n\n    if not os.path.exists(file_path):\n        response = requests.get(url, timeout=30)\n        response.raise_for_status()\n        text_data = response.text\n        with open(file_path, \"w\", encoding=\"utf-8\") as file:\n            file.write(text_data)\n    else:\n        with open(file_path, \"r\", encoding=\"utf-8\") as file:\n            text_data = file.read()\n\n    ##############################\n    # 2. 모델 및 옵티마이저 초기화\n    ##############################\n    model = GPTModel(gpt_config)\n    model.to(device) # 모델을 GPU 메모리로 올림\n    \n    # AdamW: 가중치 감쇠(Weight Decay)가 적용된 Adam 옵티마이저\n    # Weight Decay는 모델이 너무 복잡해지지 않도록 규제(Regularization)하는 역할\n    # TODO: AdamW에 넘길 파라미터 이터레이터와 학습률 키워드를 채우세요.\n    # 힌트: 첫 번째 인자는 model.parameters(), 학습률은 lr=settings[\"learning_rate\"] 형태입니다.\n    optimizer = torch.optim.AdamW(\n        model.parameters(), lr=settings[\"learning_rate\"], weight_decay=settings[\"weight_decay\"]\n    )\n\n    ##############################\n    # 3. 데이터 로더 구축\n    ##############################\n    # 전체 텍스트를 9:1 비율로 훈련용과 검증용으로 나눔\n    train_ratio = 0.90\n    split_idx = int(train_ratio * len(text_data))\n\n    # 훈련 데이터 로더: 순서를 섞음(Shuffle=True)\n    train_loader = create_dataloader_v1(\n        text_data[:split_idx],\n        batch_size=settings[\"batch_size\"],\n        max_length=gpt_config[\"context_length\"],\n        stride=gpt_config[\"context_length\"],\n        drop_last=True,\n        shuffle=True,\n        num_workers=0\n    )\n\n    # 검증 데이터 로더: 순서를 섞지 않음(Shuffle=False) -> 평가는 일관되게\n    val_loader = create_dataloader_v1(\n        text_data[split_idx:],\n        batch_size=settings[\"batch_size\"],\n        max_length=gpt_config[\"context_length\"],\n        stride=gpt_config[\"context_length\"],\n        drop_last=False,\n        shuffle=False,\n        num_workers=0\n    )\n\n    ##############################\n    # 4. 훈련 시작\n    ##############################\n    tokenizer = tiktoken.get_encoding(\"gpt2\") # BPE 토크나이저\n\n    train_losses, val_losses, tokens_seen = train_model_simple(\n        model, train_loader, val_loader, optimizer, device,\n        num_epochs=settings[\"num_epochs\"], eval_freq=5, eval_iter=1,\n        start_context=\"Every effort moves you\", tokenizer=tokenizer\n    )\n\n    return train_losses, val_losses, tokens_seen, model"}, {"number": 6, "code_number": 6, "type": "code", "source": "\n# GPT-2 Small (124M) 모델 설정\nGPT_CONFIG_124M = {\n    \"vocab_size\": 50257,    # 어휘 크기\n    \"context_length\": 256,  # 훈련 속도를 위해 원본(1024)보다 줄임\n    \"emb_dim\": 768,         # 임베딩 벡터 차원\n    \"n_heads\": 12,          # 어텐션 헤드 개수\n    \"n_layers\": 12,         # 레이어 깊이\n    \"drop_rate\": 0.1,       # 과적합 방지 드롭아웃\n    \"qkv_bias\": False       \n}\n\n# 학습 하이퍼파라미터\nOTHER_SETTINGS = {\n    \"learning_rate\": 5e-4, \n    \"num_epochs\": 10,       \n    \"batch_size\": 2,        \n    \"weight_decay\": 0.1     \n}\n\n###########################\n# 메인 실행: 훈련\n###########################\ntrain_losses, val_losses, tokens_seen, model = main(GPT_CONFIG_124M, OTHER_SETTINGS)\n\n###########################\n# 훈련 결과 시각화 및 저장\n###########################\n\n# 에포크 축 생성 (0부터 num_epochs까지)\nepochs_tensor = torch.linspace(0, OTHER_SETTINGS[\"num_epochs\"], len(train_losses))\nplot_losses(epochs_tensor, tokens_seen, train_losses, val_losses)\nplt.savefig(\"outputs/loss.pdf\")\n\n# 모델 저장 및 로드 테스트\ntorch.save(model.state_dict(), \"outputs/model.pth\")\n\n# 디바이스 설정 (모델 로드 전에 정의 필요)\ndevice = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n\n# 모델 다시 불러오기 테스트\nmodel = GPTModel(GPT_CONFIG_124M) # 1. 빈 모델 생성 (현재 CPU에 있음)\nmodel.load_state_dict(torch.load(\"outputs/model.pth\", weights_only=True)) # 2. 가중치 로드\nmodel.to(device) # <--- [핵심 수정] 3. 모델을 GPU로 이동시켜야 함\n\ntorch.manual_seed(123)\n###########################\n# 생성 테스트 (Inference)\n###########################\ntokenizer = tiktoken.get_encoding(\"gpt2\")\n\n# 훈련된 모델로 텍스트 생성 시도\n# Temperature=1.4로 설정하여 다소 창의적/다양한 문장 생성 유도\ntoken_ids = generate(\n    model=model,\n    idx=text_to_token_ids(\"Every effort moves you\", tokenizer).to(device),\n    max_new_tokens=15,\n    context_size=GPT_CONFIG_124M[\"context_length\"]\n)\n\nprint(\"출력 텍스트:\\n\", token_ids_to_text(token_ids, tokenizer))"}, {"number": 7, "code_number": 7, "type": "code", "source": ""}], "blanks": [{"id": "blank-cross-entropy", "label": "Token 단위 Cross Entropy", "answer": "torch.nn.functional.cross_entropy(\n    logits.flatten(0, 1),\n    target_batch.flatten()\n)"}, {"id": "blank-zero-grad", "label": "Gradient 초기화", "answer": "optimizer.zero_grad()"}, {"id": "blank-backward", "label": "역전파", "answer": "loss.backward()"}, {"id": "blank-step", "label": "Optimizer 갱신", "answer": "optimizer.step()"}]}, "Chapter_6_Excercise_Finetuning_Classification.ipynb": {"page": "llm_chapter_6a_classification_subjective_test", "cells": [{"number": 1, "code_number": 1, "type": "code", "source": "# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\n# Source for \"Build a Large Language Model From Scratch\"\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\n# Code: https://github.com/rasbt/LLMs-from-scratch\n\n# 6장의 주요 내용을 요약한 파일: 분류(Classification)를 위한 GPT 미세 조정\nimport requests\nimport zipfile\nimport os\nfrom pathlib import Path\nimport time\n\nimport matplotlib.pyplot as plt\nimport pandas as pd\nimport tiktoken\nimport torch\nfrom torch.utils.data import Dataset, DataLoader\n\n# 이전 챕터나 별도 모듈에서 정의된 GPT 모델 관련 함수들 임포트\nfrom previous_chapters import GPTModel, load_gpt2_model\n\n# -----------------------------------------------------------------------------\n# 1. 데이터 준비 유틸리티 함수들\n# -----------------------------------------------------------------------------\n\ndef download_and_unzip_spam_data(url, zip_path, extracted_path, data_file_path):\n    \"\"\"\n    스팸 데이터셋(SMS Spam Collection)을 다운로드하고 압축을 해제하는 함수\n    \"\"\"\n    if data_file_path.exists():\n        print(f\"{data_file_path} already exists. Skipping download and extraction.\")\n        return\n\n    # 파일 다운로드 (스트리밍 방식)\n    response = requests.get(url, stream=True, timeout=60)\n    response.raise_for_status()\n    with open(zip_path, \"wb\") as out_file:\n        for chunk in response.iter_content(chunk_size=8192):\n            if chunk:\n                out_file.write(chunk)\n\n    # 압축 해제\n    with zipfile.ZipFile(zip_path, \"r\") as zip_ref:\n        zip_ref.extractall(extracted_path)\n\n    # 압축 해제된 파일에 .tsv 확장자 추가 (Pandas로 읽기 편하게)\n    original_file_path = Path(extracted_path) / \"SMSSpamCollection\"\n    os.rename(original_file_path, data_file_path)\n    print(f\"File downloaded and saved as {data_file_path}\")\n\n\ndef create_balanced_dataset(df):\n    \"\"\"\n    데이터 불균형 해결을 위한 함수.\n    스팸(spam) 데이터 수에 맞춰 햄(ham, 정상 메일) 데이터를 언더샘플링합니다.\n    \"\"\"\n    # \"spam\" 라벨의 개수 계산\n    num_spam = df[df[[BLANK:blank-ch6a-label]] == \"spam\"].shape[0]\n\n    # \"ham\" 데이터 중에서 \"spam\" 개수만큼만 무작위 추출\n    ham_subset = df[df[\"Label\"] == \"ham\"].sample(num_spam, random_state=123)\n\n    # 두 데이터셋 병합\n    balanced_df = pd.concat([ham_subset, df[df[\"Label\"] == \"spam\"]])\n\n    return balanced_df\n\n\ndef random_split(df, train_frac, validation_frac):\n    \"\"\"\n    데이터셋을 학습(Train), 검증(Validation), 테스트(Test) 셋으로 분할하는 함수\n    \"\"\"\n    # 전체 데이터 섞기\n    df = df.sample(frac=1, random_state=123).reset_index(drop=True)\n\n    # 분할 지점(인덱스) 계산\n    train_end = int(len(df) * train_frac)\n    validation_end = train_end + int(len(df) * validation_frac)\n\n    # 데이터 분할\n    train_df = df[:train_end]\n    validation_df = df[train_end:validation_end]\n    test_df = df[validation_end:]\n\n    return train_df, validation_df, test_df\n\n\nclass SpamDataset(Dataset):\n    \"\"\"\n    PyTorch Dataset 클래스 정의.\n    텍스트를 토큰화하고, 패딩(Padding) 처리를 수행합니다.\n    \"\"\"\n    def __init__(self, csv_file, tokenizer, max_length=None, pad_token_id=50256):\n        self.data = pd.read_csv(csv_file)\n\n        # 1. 텍스트 데이터를 토큰 ID 리스트로 변환 (Tokenization)\n        self.encoded_texts = [\n            tokenizer.encode(text) for text in self.data[\"Text\"]\n        ]\n\n        # 2. 최대 길이(max_length) 설정\n        if max_length is None:\n            self.max_length = self._longest_encoded_length()\n        else:\n            self.max_length = max_length\n            # max_length보다 긴 문장은 잘라냄 (Truncation)\n            # TODO: 시퀀스를 최대 길이로 잘라낼 끝 인덱스를 채우세요.\n            # 힌트: 설정된 최대 길이 `self.max_length`로 슬라이싱하면 됩니다.\n            self.encoded_texts = [\n                [[BLANK:blank-ch6a-truncate]]\n                for encoded_text in self.encoded_texts\n            ]\n\n        # 3. 패딩(Padding): 모든 시퀀스 길이를 max_length로 맞춤\n        # GPT-2의 <|endoftext|> 토큰 ID인 50256을 패딩 값으로 사용\n        # TODO: 패딩에 사용할 토큰 ID를 채우세요.\n        # 힌트: 함수 파라미터로 전달된 `pad_token_id`를 사용합니다.\n        self.encoded_texts = [\n            encoded_text + [[BLANK:blank-ch6a-padding]] * (self.max_length - len(encoded_text))\n            for encoded_text in self.encoded_texts\n        ]\n\n    def __getitem__(self, index):\n        encoded = self.encoded_texts[index]\n        # TODO: 레이블을 가져올 DataFrame 컬럼명을 채우세요.\n        # 힌트: 데이터셋의 정답 컬럼 이름은 'Label'입니다.\n        label = self.data.iloc[index][\"Label\"]\n        # 텐서 형태로 반환 (입력 데이터, 정답 라벨)\n        return (\n            torch.tensor(encoded, dtype=torch.long),\n            torch.tensor(label, dtype=torch.long)\n        )\n\n    def __len__(self):\n        return len(self.data)\n\n    def _longest_encoded_length(self):\n        max_length = 0\n        for encoded_text in self.encoded_texts:\n            encoded_length = len(encoded_text)\n            if encoded_length > max_length:\n                max_length = encoded_length\n        return max_length\n\n\n# -----------------------------------------------------------------------------\n# 2. 평가 및 학습 관련 함수들\n# -----------------------------------------------------------------------------\n\ndef calc_accuracy_loader(data_loader, model, device, num_batches=None):\n    \"\"\"\n    데이터 로더를 순회하며 모델의 정확도(Accuracy)를 계산\n    \"\"\"\n    model.eval()  # 평가 모드 설정 (Dropout 비활성화 등)\n    correct_predictions, num_examples = 0, 0\n\n    if num_batches is None:\n        num_batches = len(data_loader)\n    else:\n        num_batches = min(num_batches, len(data_loader))\n        \n    for i, (input_batch, target_batch) in enumerate(data_loader):\n        if i < num_batches:\n            input_batch, target_batch = input_batch.to(device), target_batch.to(device)\n\n            with torch.no_grad():\n                # GPT 모델은 시퀀스를 출력하므로, 분류를 위해서는 '마지막 토큰'의 출력만 사용\n                # logits shape: [batch_size, seq_len, vocab_size 또는 num_classes]\n                logits = model(input_batch)[:, -1, :]  \n            \n            predicted_labels = torch.argmax(logits, dim=-1)\n\n            num_examples += predicted_labels.shape[0]\n            correct_predictions += (predicted_labels == target_batch).sum().item()\n        else:\n            break\n    return correct_predictions / num_examples\n\n\ndef calc_loss_batch(input_batch, target_batch, model, device):\n    \"\"\"\n    단일 배치에 대한 손실(Loss) 계산\n    \"\"\"\n    input_batch, target_batch = input_batch.to(device), target_batch.to(device)\n    # TODO: 분류에 사용할 시퀀스 내 위치 인덱스를 채우세요.\n    # 힌트: GPT는 시퀀스의 마지막 토큰 출력만 분류 예측에 사용합니다.\n    logits = model(input_batch)[:, -1, :]  \n    # Cross Entropy Loss 계산\n    loss = torch.nn.functional.cross_entropy(logits, target_batch)\n    return loss\n\n\ndef calc_loss_loader(data_loader, model, device, num_batches=None):\n    \"\"\"\n    데이터 로더 전체에 대한 평균 손실 계산\n    \"\"\"\n    total_loss = 0.\n    if len(data_loader) == 0:\n        return float(\"nan\")\n    elif num_batches is None:\n        num_batches = len(data_loader)\n    else:\n        num_batches = min(num_batches, len(data_loader))\n        \n    for i, (input_batch, target_batch) in enumerate(data_loader):\n        if i < num_batches:\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\n            total_loss += loss.item()\n        else:\n            break\n    return total_loss / num_batches\n\n\ndef evaluate_model(model, train_loader, val_loader, device, eval_iter):\n    \"\"\"\n    현재 모델의 Train Loss와 Validation Loss를 평가\n    \"\"\"\n    model.eval()\n    with torch.no_grad():\n        train_loss = calc_loss_loader(train_loader, model, device, num_batches=eval_iter)\n        val_loss = calc_loss_loader(val_loader, model, device, num_batches=eval_iter)\n    model.train()\n    return train_loss, val_loss\n\n\ndef train_classifier_simple(model, train_loader, val_loader, optimizer, device, num_epochs,\n                            eval_freq, eval_iter):\n    \"\"\"\n    메인 학습 루프 함수\n    \"\"\"\n    # 손실과 정확도 기록용 리스트\n    train_losses, val_losses, train_accs, val_accs = [], [], [], []\n    examples_seen, global_step = 0, -1\n\n    for epoch in range(num_epochs):\n        model.train()  # 학습 모드 설정\n\n        for input_batch, target_batch in train_loader:\n            optimizer.zero_grad()  # 이전 기울기 초기화\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\n            loss.backward()  # 역전파 (Gradient 계산)\n            optimizer.step()  # 가중치 업데이트\n            \n            examples_seen += input_batch.shape[0]\n            global_step += 1\n\n            # 주기적으로 평가 수행 (eval_freq 스텝마다)\n            if global_step % eval_freq == 0:\n                train_loss, val_loss = evaluate_model(\n                    model, train_loader, val_loader, device, eval_iter)\n                train_losses.append(train_loss)\n                val_losses.append(val_loss)\n                print(f\"Ep {epoch+1} (Step {global_step:06d}): \"\n                      f\"Train loss {train_loss:.3f}, Val loss {val_loss:.3f}\")\n\n        # 에폭이 끝날 때마다 정확도 계산 및 출력\n        train_accuracy = calc_accuracy_loader(train_loader, model, device, num_batches=eval_iter)\n        val_accuracy = calc_accuracy_loader(val_loader, model, device, num_batches=eval_iter)\n        print(f\"Training accuracy: {train_accuracy*100:.2f}% | \", end=\"\")\n        print(f\"Validation accuracy: {val_accuracy*100:.2f}%\")\n        train_accs.append(train_accuracy)\n        val_accs.append(val_accuracy)\n\n    return train_losses, val_losses, train_accs, val_accs, examples_seen\n\n\ndef plot_values(epochs_seen, examples_seen, train_values, val_values, label=\"loss\"):\n    \"\"\"\n    학습 결과(Loss, Accuracy)를 그래프로 시각화하여 저장\n    \"\"\"\n    fig, ax1 = plt.subplots(figsize=(5, 3))\n\n    # 에폭(Epoch) 기준 그래프\n    ax1.plot(epochs_seen, train_values, label=f\"Training {label}\")\n    ax1.plot(epochs_seen, val_values, linestyle=\"-.\", label=f\"Validation {label}\")\n    ax1.set_xlabel(\"Epochs\")\n    ax1.set_ylabel(label.capitalize())\n    ax1.legend()\n\n    # 처리한 예제 수(Examples seen) 기준 보조 축 추가\n    ax2 = ax1.twiny()\n    ax2.plot(examples_seen, train_values, alpha=0)\n    ax2.set_xlabel(\"Examples seen\")\n\n    fig.tight_layout()\n    plt.savefig(f\"outputs/{label}-plot.pdf\")\n    # plt.show()"}, {"number": 2, "code_number": 2, "type": "code", "source": "# -----------------------------------------------------------------------------\n# 3. 메인 실행 블록\n# -----------------------------------------------------------------------------\n\ntest_mode = False\n########################################\n# 1단계: 데이터셋 다운로드 및 준비\n########################################\n\nurl = \"https://archive.ics.uci.edu/static/public/228/sms+spam+collection.zip\"\nzip_path = \"datas/sms_spam_collection.zip\"\nextracted_path = \"datas/sms_spam_collection\"\ndata_file_path = Path(extracted_path) / \"SMSSpamCollection.tsv\"\n\ntry:\n    download_and_unzip_spam_data(url, zip_path, extracted_path, data_file_path)\nexcept (requests.exceptions.RequestException, TimeoutError) as e:\n    print(f\"Primary URL failed: {e}. Trying backup URL...\")\n    url = \"https://f001.backblazeb2.com/file/LLMs-from-scratch/sms%2Bspam%2Bcollection.zip\"\n    download_and_unzip_spam_data(url, zip_path, extracted_path, data_file_path)\n\n# 데이터 로드 및 전처리\ndf = pd.read_csv(data_file_path, sep=\"\\t\", header=None, names=[\"Label\", \"Text\"])\nbalanced_df = create_balanced_dataset(df) # 50:50 균형 데이터셋 생성\nbalanced_df[\"Label\"] = balanced_df[\"Label\"].map({\"ham\": 0, \"spam\": 1}) # 라벨 인코딩\n\n# Train/Val/Test 분할 및 CSV 저장\ntrain_df, validation_df, test_df = random_split(balanced_df, 0.7, 0.1)\ntrain_df.to_csv(\"datas/train.csv\", index=None)\nvalidation_df.to_csv(\"datas/validation.csv\", index=None)\ntest_df.to_csv(\"datas/test.csv\", index=None)\n\n########################################\n# 2단계: 데이터 로더 생성\n########################################\ntokenizer = tiktoken.get_encoding(\"gpt2\")\n\n# 학습 데이터셋 생성\ntrain_dataset = SpamDataset(\n    csv_file=\"datas/train.csv\",\n    max_length=None, # 가장 긴 문장에 맞춰 자동 설정\n    tokenizer=tokenizer\n)\n\n# 검증/테스트 데이터셋은 학습 데이터셋의 max_length를 따름 (일관성 유지)\nval_dataset = SpamDataset(\n    csv_file=\"datas/validation.csv\",\n    max_length=train_dataset.max_length,\n    tokenizer=tokenizer\n)\n\ntest_dataset = SpamDataset(\n    csv_file=\"datas/test.csv\",\n    max_length=train_dataset.max_length,\n    tokenizer=tokenizer\n)\n\nnum_workers = 0\nbatch_size = 8\ntorch.manual_seed(123)\n\n# DataLoader 생성\ntrain_loader = DataLoader(\n    dataset=train_dataset,\n    batch_size=batch_size,\n    shuffle=True, # 학습 데이터는 섞음\n    num_workers=num_workers,\n    drop_last=True,\n)\n\nval_loader = DataLoader(\n    dataset=val_dataset,\n    batch_size=batch_size,\n    num_workers=num_workers,\n    drop_last=False,\n)\n\ntest_loader = DataLoader(\n    dataset=test_dataset,\n    batch_size=batch_size,\n    num_workers=num_workers,\n    drop_last=False,\n)\n\n########################################\n# 3단계: 사전 학습된 모델 로드 (Pre-trained Model Loading)\n########################################\n\nif test_mode:\n    # 테스트 모드일 때는 아주 작은 더미 모델 생성\n    BASE_CONFIG = {\n        \"vocab_size\": 50257,\n        \"context_length\": 120,\n        \"drop_rate\": 0.0,\n        \"qkv_bias\": False,\n        \"emb_dim\": 12,\n        \"n_layers\": 1,\n        \"n_heads\": 2\n    }\n    model = GPTModel(BASE_CONFIG)\n    model.eval()\n    device = \"cpu\"\n\nelse:\n    # 실제 GPT-2 Small (124M 파라미터) 모델 설정 및 가중치 로드\n    CHOOSE_MODEL = \"gpt2-small (124M)\"\n    \n    BASE_CONFIG = {\n        \"vocab_size\": 50257,     \n        \"context_length\": 1024,  \n        \"drop_rate\": 0.0,        \n        \"qkv_bias\": True         \n    }\n\n    model_configs = {\n        \"gpt2-small (124M)\": {\"emb_dim\": 768, \"n_layers\": 12, \"n_heads\": 12},\n        # 다른 모델 사이즈 설정들...\n        \"gpt2-medium (355M)\": {\"emb_dim\": 1024, \"n_layers\": 24, \"n_heads\": 16},\n        \"gpt2-large (774M)\": {\"emb_dim\": 1280, \"n_layers\": 36, \"n_heads\": 20},\n        \"gpt2-xl (1558M)\": {\"emb_dim\": 1600, \"n_layers\": 48, \"n_heads\": 25},\n    }\n\n    BASE_CONFIG.update(model_configs[CHOOSE_MODEL])\n\n    # 데이터셋의 길이가 모델의 컨텍스트 길이를 초과하는지 확인\n    assert train_dataset.max_length <= BASE_CONFIG[\"context_length\"], (\n        f\"Dataset length {train_dataset.max_length} exceeds model's context \"\n        f\"length {BASE_CONFIG['context_length']}. Reinitialize data sets with \"\n        f\"`max_length={BASE_CONFIG['context_length']}`\"\n    )\n\n    model_name = \"gpt2-small-124M.pth\"\n    model = load_gpt2_model(model_name, BASE_CONFIG)\n\n    device = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n\n########################################\n# 4단계: 모델 수정 및 미세 조정 설정 (Fine-tuning Setup)\n########################################\n\n# 1. 모든 파라미터를 고정(Freeze)하여 학습되지 않게 설정\n# TODO: 파라미터 동결을 위한 값을 채우세요.\n# 힌트: 파라미터를 학습에서 제외하려면 requires_grad를 False로 설정합니다.\nfor param in model.parameters():\n    param.requires_grad = ????\n\ntorch.manual_seed(123)\n\n# 2. 출력층(Head) 교체: 기존 50257개 단어 예측 -> 2개 클래스(스팸/햄) 예측\n# 이 새로운 층은 기본적으로 requires_grad=True 상태임\nnum_classes = 2\n# region [출력층(Head) 교체]\n# TODO: 출력층의 클래스 수를 채우세요.\n# 힌트: 이진 분류(스팸/햄) 문제이므로 위에서 정의한 num_classes를 사용합니다.\nmodel.out_head = torch.nn.Linear(in_features=BASE_CONFIG[\"emb_dim\"], out_features=????)\n# endregion\n\nmodel.to(device)\n\n# 3. 추가적으로 마지막 트랜스포머 블록과 정규화 층을 학습 가능하도록 잠금 해제 (Unfreeze)\n# -> 이렇게 하면 출력층과 모델의 마지막 부분만 데이터에 맞게 조정됨 (효율적 학습)\n# region [마지막 트랜스포머 블록과 정규화 층 잠금 해제]\n# TODO: 학습할 마지막 블록 인덱스와 학습 허용 값을 채우세요.\n# 힌트: 마지막 트랜스포머 블록만 학습하려면 인덱스 -1과 requires_grad = True를 사용합니다.\nfor param in model.trf_blocks[????].parameters():\n    param.requires_grad = ????\n\n# TODO: 정규화 층 학습 허용 값을 채우세요.\n# 힌트: requires_grad를 True로 설정하면 해당 파라미터가 학습 대상이 됩니다.\nfor param in model.final_norm.parameters():\n    param.requires_grad = ????\n# endregion\n\n########################################\n# 5단계: 모델 미세 조정 (Fine-tuning) 실행\n########################################\n\nstart_time = time.time()\ntorch.manual_seed(123)\n\n# 옵티마이저 설정 (학습 가능한 파라미터만 전달됨)\noptimizer = torch.optim.AdamW(model.parameters(), lr=5e-5, weight_decay=0.1)\n\nnum_epochs = 5\n# 학습 함수 호출\ntrain_losses, val_losses, train_accs, val_accs, examples_seen = train_classifier_simple(\n    model, train_loader, val_loader, optimizer, device,\n    num_epochs=num_epochs, eval_freq=50, eval_iter=5,\n)\n\nend_time = time.time()\nexecution_time_minutes = (end_time - start_time) / 60\nprint(f\"Training completed in {execution_time_minutes:.2f} minutes.\")\n\n########################################\n# 6단계: 결과 시각화\n########################################\n\n# Loss 그래프 그리기\nepochs_tensor = torch.linspace(0, num_epochs, len(train_losses))\nexamples_seen_tensor = torch.linspace(0, examples_seen, len(train_losses))\nplot_values(epochs_tensor, examples_seen_tensor, train_losses, val_losses)\n\n# Accuracy 그래프 그리기\nepochs_tensor = torch.linspace(0, num_epochs, len(train_accs))\nexamples_seen_tensor = torch.linspace(0, examples_seen, len(train_accs))\nplot_values(epochs_tensor, examples_seen_tensor, train_accs, val_accs, label=\"accuracy\")"}, {"number": 3, "code_number": 3, "type": "code", "source": ""}], "blanks": [{"id": "blank-ch6a-truncate", "label": "최대 길이 truncation", "answer": "encoded_text[:self.max_length]"}, {"id": "blank-ch6a-padding", "label": "Padding token ID", "answer": "[pad_token_id]"}, {"id": "blank-ch6a-label", "label": "정답 Label column", "answer": "[\"Label\"]"}]}, "Chapter_6_Excercise_Finetuning_Classification_LoRA.ipynb": {"page": "llm_chapter_6b_lora_subjective_test", "cells": [{"number": 1, "code_number": 1, "type": "code", "source": "import math\nimport time\nimport requests\nfrom pathlib import Path\nimport pandas as pd\nimport torch\nimport torch.nn as nn\nimport tiktoken\nfrom torch.utils.data import DataLoader\nimport matplotlib.pyplot as plt # 그래프 저장을 위해 추가\n\n# 로컬 모듈 임포트 (previous_chapters.py가 필요합니다)\nfrom previous_chapters import (\n    download_and_unzip_spam_data,\n    create_balanced_dataset,\n    random_split,\n    SpamDataset,\n    GPTModel,\n    download_model,\n    calc_accuracy_loader,\n    train_classifier_simple,\n    plot_values # 그래프 그리기 함수 추가\n)"}, {"number": 2, "code_number": 2, "type": "code", "source": "# -----------------------------------------------------------------------------\n# 1. 설정 및 하이퍼파라미터\n# -----------------------------------------------------------------------------\nBASE_CONFIG = {\n    \"vocab_size\": 50257,\n    \"context_length\": 1024,\n    \"drop_rate\": 0.0,\n    \"qkv_bias\": True,\n    \"emb_dim\": 768, \"n_layers\": 12, \"n_heads\": 12\n}\n\nBATCH_SIZE = 8\nNUM_EPOCHS = 5\nLEARNING_RATE = 8e-4\nLORA_RANK = 16\nLORA_ALPHA = 16"}, {"number": 3, "code_number": 3, "type": "code", "source": "###중요: LoRA 구현 부분\n# -----------------------------------------------------------------------------\n# 2. LoRA 클래스 및 함수 정의\n# -----------------------------------------------------------------------------\nclass LoRALayer(nn.Module):\n    def __init__(self, in_dim, out_dim, rank, alpha):\n        \"\"\"\n        LoRA(Low-Rank Adaptation) 레이어 초기화\n        \"\"\"\n        super().__init__()\n        # TODO: LoRA A 행렬의 rank 차원을 채우세요.\n        # 힌트: A 행렬 크기는 (in_dim, rank)입니다.\n        self.A = [[BLANK:blank-ch6b-a]]\n        nn.init.kaiming_uniform_(self.A, a=math.sqrt(5))\n        \n        # TODO: LoRA B 행렬의 rank 차원을 채우세요.\n        # 힌트: B 행렬 크기는 (rank, out_dim)입니다.\n        self.B = nn.Parameter(torch.zeros(self.rank, out_dim))\n        \n        self.alpha = alpha\n        self.rank = rank\n\n    def forward(self, x):\n        # region [LoRA 어댑터 적용]\n        # TODO: LoRA forward 식의 파라미터명을 채우세요.\n        # 힌트: alpha/rank 스케일과 A, B 행렬곱 순서를 맞추세요.\n        x = [[BLANK:blank-ch6b-delta]]\n        # endregion\n        return x\n\nclass LinearWithLoRA(nn.Module):\n    \"\"\"\n    기존의 Linear 레이어를 감싸서 LoRA 어댑터를 추가한 클래스\n    \"\"\"\n    def __init__(self, linear, rank, alpha):\n        super().__init__()\n        self.linear = linear\n        self.lora = LoRALayer(\n            linear.in_features, linear.out_features, rank, alpha\n        )\n\n    def forward(self, x):\n        # region [기존 Linear와 LoRA 출력 합산]\n        # TODO: LoRA 잔차 호출 대상을 채우세요.\n        # 힌트: 기존 linear 출력에 lora(x)를 더해 반환합니다.\n        return [[BLANK:blank-ch6b-residual]]\n        # endregion\n        \ndef replace_linear_with_lora(model, rank, alpha):\n    \"\"\"\n    모델 내의 모든 Linear 레이어를 찾아 LoRA가 적용된 레이어로 교체\n    \"\"\"\n    for name, module in model.named_children():\n        # TODO: LoRA 교체 대상 레이어 타입을 채우세요.\n        # 힌트: 대상은 torch.nn.Linear 레이어입니다.\n        if isinstance(module, torch.nn.Linear):\n            # 기존 Linear 레이어를 LinearWithLoRA로 교체\n            setattr(model, name, LinearWithLoRA(module, rank, alpha))\n        else:\n            # 재귀 호출\n            replace_linear_with_lora(module, rank, alpha)"}, {"number": 4, "code_number": 4, "type": "code", "source": "def main():\n    # 시드 설정\n    torch.manual_seed(123)\n    \n    # 장치 설정\n    device = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n    print(f\"사용 장치: {device}\")\n\n    # --- 데이터셋 준비 ---\n    print(\"데이터셋 준비 중...\")\n    url = \"https://archive.ics.uci.edu/static/public/228/sms+spam+collection.zip\"\n    zip_path = \"datas/sms_spam_collection.zip\"\n    extracted_path = \"datas/sms_spam_collection\"\n    data_file_path = Path(extracted_path) / \"SMSSpamCollection.tsv\"\n\n    try:\n        download_and_unzip_spam_data(url, zip_path, extracted_path, data_file_path)\n    except (requests.exceptions.RequestException, TimeoutError):\n        # 백업 URL 시도\n        url = \"https://f001.backblazeb2.com/file/LLMs-from-scratch/sms%2Bspam%2Bcollection.zip\"\n        download_and_unzip_spam_data(url, zip_path, extracted_path, data_file_path)\n\n    df = pd.read_csv(data_file_path, sep=\"\\t\", header=None, names=[\"Label\", \"Text\"])\n    balanced_df = create_balanced_dataset(df)\n    balanced_df[\"Label\"] = balanced_df[\"Label\"].map({\"ham\": 0, \"spam\": 1})\n\n    train_df, validation_df, test_df = random_split(balanced_df, 0.7, 0.1)\n    \n    # 임시 파일 저장 (Dataset 클래스 사용을 위해)\n    train_df.to_csv(\"datas/train.csv\", index=None)\n    validation_df.to_csv(\"datas/validation.csv\", index=None)\n    test_df.to_csv(\"datas/test.csv\", index=None)\n\n    tokenizer = tiktoken.get_encoding(\"gpt2\")\n    train_dataset = SpamDataset(\"datas/train.csv\", max_length=None, tokenizer=tokenizer)\n    val_dataset = SpamDataset(\"datas/validation.csv\", max_length=train_dataset.max_length, tokenizer=tokenizer)\n    test_dataset = SpamDataset(\"datas/test.csv\", max_length=train_dataset.max_length, tokenizer=tokenizer)\n\n    train_loader = DataLoader(dataset=train_dataset, batch_size=BATCH_SIZE, shuffle=True, drop_last=True)\n    val_loader = DataLoader(dataset=val_dataset, batch_size=BATCH_SIZE, drop_last=False)\n    test_loader = DataLoader(dataset=test_dataset, batch_size=BATCH_SIZE, drop_last=False)\n\n    # --- 모델 준비 ---\n    print(\"모델 로드 중...\")\n\n    file_name = \"gpt2-small-124M.pth\"\n    model_path = f\"./models/gpt2/{file_name}\"\n    download_model(file_name, model_path)\n\n    # Policy Model (학습 대상)\n    model = GPTModel(BASE_CONFIG)\n    model.load_state_dict(torch.load(model_path, map_location=\"cpu\", weights_only=True))\n    model.to(device)\n\n    # 출력 헤드 교체 (분류용)\n    num_classes = 2\n    model.out_head = torch.nn.Linear(in_features=768, out_features=num_classes)\n    \n    # --- LoRA 적용 ---\n    print(\"LoRA 레이어 적용 및 파라미터 동결 중...\")\n    # 1. 모든 파라미터 동결\n    # TODO: 파라미터 학습 여부 값을 채우세요.\n    # 힌트: 전체 동결 단계에서는 False를 설정합니다.\n    for param in model.parameters():\n        param.requires_grad = ????\n    \n    # 2. Linear 레이어를 LoRA로 교체 (LoRA 파라미터는 새로 생성되므로 requires_grad=True 상태)\n    # TODO: LoRA 주입 헬퍼 함수명을 채우세요.\n    # 힌트: 모델의 Linear 레이어를 LoRA 버전으로 교체하는 함수를 호출합니다.\n    ????(model, rank=LORA_RANK, alpha=LORA_ALPHA)\n    \n    model.to(device)\n\n    # 학습 가능 파라미터 확인\n    total_params = sum(p.numel() for p in model.parameters() if p.requires_grad)\n    print(f\"총 학습 가능 LoRA 파라미터 수: {total_params:,}\")\n\n    # --- 학습 실행 ---\n    print(\"학습 시작...\")\n    optimizer = torch.optim.AdamW(model.parameters(), lr=LEARNING_RATE, weight_decay=0.1)\n    \n    start_time = time.time()\n    # 반환값 캡처 (loss 및 accuracy 기록)\n    train_losses, val_losses, train_accs, val_accs, examples_seen = train_classifier_simple(\n        model, train_loader, val_loader, optimizer, device,\n        num_epochs=NUM_EPOCHS, eval_freq=50, eval_iter=5,\n    )\n    end_time = time.time()\n    print(f\"학습 완료 (소요 시간: {(end_time - start_time) / 60:.2f}분)\")\n\n    # --- 결과 시각화 (Loss) ---\n    print(\"학습 결과 시각화 중...\")\n    epochs_tensor = torch.linspace(0, NUM_EPOCHS, len(train_losses))\n    examples_seen_tensor = torch.linspace(0, examples_seen, len(train_losses))\n    \n    # plot_values 함수 호출\n    plot_values(epochs_tensor, examples_seen_tensor, train_losses, val_losses, label=\"loss\")\n    \n    # --- 최종 평가 ---\n    print(\"최종 모델 평가 중...\")\n    train_acc = calc_accuracy_loader(train_loader, model, device)\n    val_acc = calc_accuracy_loader(val_loader, model, device)\n    test_acc = calc_accuracy_loader(test_loader, model, device)\n\n    print(f\"훈련 정확도: {train_acc*100:.2f}%\")\n    print(f\"검증 정확도: {val_acc*100:.2f}%\")\n    print(f\"테스트 정확도: {test_acc*100:.2f}%\")"}, {"number": 5, "code_number": 5, "type": "code", "source": "main()"}], "blanks": [{"id": "blank-ch6b-a", "label": "LoRA A down-projection", "answer": "nn.Parameter(torch.empty(in_dim, self.rank))"}, {"id": "blank-ch6b-delta", "label": "LoRA scaled delta", "answer": "(self.alpha / self.rank) * (x @ self.A @ self.B)"}, {"id": "blank-ch6b-residual", "label": "Linear + LoRA 결과 결합", "answer": "self.linear(x) + self.lora(x)"}]}, "Chapter_7_Exercise_Follow_Instructions.ipynb": {"page": "llm_chapter_7a_instruction_subjective_test", "cells": [{"number": 1, "code_number": 1, "type": "code", "source": "# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\n# Source for \"Build a Large Language Model From Scratch\"\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\n# Code: https://github.com/rasbt/LLMs-from-scratch\n#\n# 7장의 코드를 기반으로 한 최소한의 Instruction Finetuning 예제 파일\n\nfrom functools import partial\nfrom importlib.metadata import version\nimport json\nimport os\nimport re\nimport time\n\nimport matplotlib.pyplot as plt\nimport requests\nimport tiktoken\nimport torch\nfrom torch.utils.data import Dataset, DataLoader\nfrom tqdm import tqdm\n\n# 로컬 파일(이전 챕터에서 작성된 유틸리티 함수들)에서 필요한 모듈 임포트\n# GPTModel 구조, 생성 함수, 학습 루프 함수 등을 가져옵니다.\nfrom previous_chapters import (\n    calc_loss_loader,\n    generate,\n    GPTModel,\n    text_to_token_ids,\n    train_model_simple,\n    token_ids_to_text,\n    load_gpt2_model\n)\n\nclass InstructionDataset(Dataset):\n    \"\"\"\n    지시사항(Instruction) 데이터셋을 처리하는 PyTorch Dataset 클래스.\n    입력 데이터(지시+입력)와 정답 데이터(응답)를 하나의 텍스트로 합쳐서 토큰화합니다.\n    \"\"\"\n    def __init__(self, data, tokenizer):\n        self.data = data\n\n        # 텍스트 데이터 미리 토큰화 (Pre-tokenize)\n        self.encoded_texts = []\n        for entry in data:\n            # 포맷팅 함수를 이용해 \"지시사항 + 입력\" 텍스트 생성\n            instruction_plus_input = format_input(entry)\n            # 정답(Response) 텍스트 생성\n            response_text = f\"\\n\\n### Response:\\n{entry['output']}\"\n            \n            # 모델은 이 전체 텍스트(질문+답변)를 보고 다음 토큰을 예측하도록 학습됨\n            full_text = instruction_plus_input + response_text\n            self.encoded_texts.append(\n                tokenizer.encode(full_text)\n            )\n\n    def __getitem__(self, index):\n        return self.encoded_texts[index]\n\n    def __len__(self):\n        return len(self.data)\n\n\ndef custom_collate_fn(\n    batch,\n    pad_token_id=50256,\n    ignore_index=-100,\n    allowed_max_length=None,\n    device=\"cpu\"\n):\n    \"\"\"\n    데이터 로더에서 배치를 만들 때 사용하는 커스텀 함수.\n    가변 길이의 시퀀스를 배치의 최대 길이에 맞춰 패딩(padding)하고, \n    정답(target) 데이터에서 패딩 부분은 손실(loss) 계산에서 제외하도록 처리합니다.\n    \"\"\"\n    # 배치 내에서 가장 긴 시퀀스 길이 계산 (패딩을 위해 +1 여유)\n    batch_max_length = max(len(item)+1 for item in batch)\n\n    # 입력(inputs)과 정답(targets) 리스트 준비\n    inputs_lst, targets_lst = [], []\n\n    for item in batch:\n        new_item = item.copy()\n        # 문장 끝 토큰 <|endoftext|> 추가\n        # TODO: 시퀀스 끝에 추가할 토큰 값을 채우세요.\n        # 힌트: 패딩 전에 구분 토큰이 필요한 경우 pad_token_id를 추가합니다.\n        new_item += [[[BLANK:blank-ch7a-eos]]]\n        \n        # 가장 긴 길이에 맞춰 패딩 추가\n        # TODO: 패딩 토큰 값을 채우세요.\n        # 힌트: 모든 샘플 길이를 맞추기 위해 pad_token_id로 채웁니다.\n        padded = new_item + [????] * (batch_max_length - len(new_item))\n        \n        # TODO: 입력과 타깃 슬라이싱 인덱스를 채우세요.\n        # 힌트: 다음 토큰 예측에서는 inputs=padded[:-1], targets=padded[1:] 형태를 만듭니다.\n        # 입력은 마지막 토큰 제외 (0 ~ n-1)\n        inputs = torch.tensor(padded[:????]) \n        # 정답은 첫 번째 토큰 제외 (1 ~ n) -> 다음 토큰 예측 문제이므로\n        targets = torch.tensor(padded[????:]) \n\n        # 중요: 패딩 부분 마스킹 처리\n        # 타겟에서 패딩 토큰인 부분은 ignore_index(-100)로 바꿔서 CrossEntropyLoss 계산 시 무시되게 함\n        mask = targets == pad_token_id\n        indices = torch.nonzero(mask).squeeze()\n        \n        # 패딩이 시작되는 지점 이후의 모든 타겟 값을 -100으로 설정\n        # region [패딩 마스킹 처리]\n        # TODO: 패딩 무시 시작 인덱스를 채우세요.\n        # 힌트: 첫 번째 패딩은 유지하고 그 뒤의 패딩부터 ignore_index로 설정합니다.\n        if indices.numel() > 1:\n            targets[indices[????:]] = ignore_index\n        # endregion\n        \n        # 선택적으로 최대 시퀀스 길이 제한 (메모리 관리 등 목적)\n        if allowed_max_length is not None:\n            inputs = inputs[:allowed_max_length]\n            targets = targets[:allowed_max_length]\n\n        inputs_lst.append(inputs)\n        targets_lst.append(targets)\n\n    # 텐서로 변환 및 디바이스(GPU/CPU)로 이동\n    inputs_tensor = torch.stack(inputs_lst).to(device)\n    targets_tensor = torch.stack(targets_lst).to(device)\n\n    return inputs_tensor, targets_tensor\n\n\ndef download_and_load_file(file_path, url):\n    \"\"\"\n    데이터 파일이 없으면 다운로드하고, JSON 형태로 로드하는 유틸리티 함수\n    \"\"\"\n    if not os.path.exists(file_path):\n        response = requests.get(url, timeout=30)\n        response.raise_for_status()\n        text_data = response.text\n        with open(file_path, \"w\", encoding=\"utf-8\") as file:\n            file.write(text_data)\n\n    with open(file_path, \"r\", encoding=\"utf-8\") as file:\n        data = json.load(file)\n\n    return data\n\n\ndef format_input(entry):\n    \"\"\"\n    Alpaca 스타일의 프롬프트 템플릿을 적용하는 함수.\n    모델에게 역할을 부여하고 입력 형식을 통일합니다.\n    \"\"\"\n    instruction_text = (\n        f\"Below is an instruction that describes a task. \"\n        f\"Write a response that appropriately completes the request.\"\n        f\"\\n\\n### Instruction:\\n{entry['instruction']}\"\n    )\n\n    # 추가적인 입력 정보(Context 등)가 있는 경우 추가\n    input_text = f\"\\n\\n### Input:\\n{entry['input']}\" if entry[\"input\"] else \"\"\n\n    return instruction_text + input_text\n\n\ndef plot_losses(epochs_seen, tokens_seen, train_losses, val_losses):\n    \"\"\"\n    학습 진행 상황(Loss)을 그래프로 시각화하여 PDF로 저장하는 함수\n    \"\"\"\n    fig, ax1 = plt.subplots(figsize=(12, 6))\n\n    # 에폭(Epoch) 기준 Loss 그래프\n    ax1.plot(epochs_seen, train_losses, label=\"Training loss\")\n    ax1.plot(epochs_seen, val_losses, linestyle=\"-.\", label=\"Validation loss\")\n    ax1.set_xlabel(\"Epochs\")\n    ax1.set_ylabel(\"Loss\")\n    ax1.legend(loc=\"upper right\")\n\n    # 처리한 토큰 수(Tokens seen) 기준 보조 x축 생성\n    ax2 = ax1.twiny() \n    ax2.plot(tokens_seen, train_losses, alpha=0) \n    ax2.set_xlabel(\"Tokens seen\")\n\n    fig.tight_layout()\n    plot_name = \"outputs/loss-plot-standalone.pdf\"\n    print(f\"Plot saved as {plot_name}\")\n    plt.savefig(plot_name)\n    # plt.show()\n\n\ndef main(test_mode=False):\n    #######################################\n    # 패키지 버전 출력 (디버깅용)\n    #######################################\n    print()\n    pkgs = [\n        \"matplotlib\",  # 시각화\n        \"tiktoken\",    # 토크나이저\n        \"torch\",       # 딥러닝 프레임워크\n        \"tqdm\",        # 진행률 표시 바\n    ]\n    for p in pkgs:\n        print(f\"{p} version: {version(p)}\")\n    print(50*\"-\")\n\n    #######################################\n    # 1. 데이터셋 다운로드 및 준비\n    #######################################\n    file_path = \"datas/instruction-data.json\"\n    url = \"https://raw.githubusercontent.com/rasbt/LLMs-from-scratch/main/ch07/01_main-chapter-code/instruction-data.json\"\n    data = download_and_load_file(file_path, url)\n\n    # 데이터 분할 (Train 85% / Test 10% / Valid 5%)\n    train_portion = int(len(data) * 0.85) \n    test_portion = int(len(data) * 0.1)   \n\n    train_data = data[:train_portion]\n    test_data = data[train_portion:train_portion + test_portion]\n    val_data = data[train_portion + test_portion:]\n\n    # 테스트 모드일 경우 아주 적은 데이터만 사용 (빠른 실행 확인용)\n    if test_mode:\n        train_data = train_data[:10]\n        val_data = val_data[:10]\n        test_data = test_data[:10]\n\n    print(\"Training set length:\", len(train_data))\n    print(\"Validation set length:\", len(val_data))\n    print(\"Test set length:\", len(test_data))\n    print(50*\"-\")\n\n    # 토크나이저 및 디바이스 설정\n    tokenizer = tiktoken.get_encoding(\"gpt2\")\n    device = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n    print(\"Device:\", device)\n    print(50*\"-\")\n\n    # 커스텀 collate 함수 설정 (partial을 사용해 고정 인자 전달)\n    customized_collate_fn = partial(custom_collate_fn, device=device, allowed_max_length=1024)\n\n    num_workers = 0\n    batch_size = 8\n    torch.manual_seed(123)\n\n    # 학습용 데이터 로더\n    train_dataset = InstructionDataset(train_data, tokenizer)\n    train_loader = DataLoader(\n        train_dataset,\n        batch_size=batch_size,\n        collate_fn=customized_collate_fn, # 커스텀 배치 처리 함수 사용\n        shuffle=True,\n        drop_last=True,\n        num_workers=num_workers\n    )\n\n    # 검증용 데이터 로더\n    val_dataset = InstructionDataset(val_data, tokenizer)\n    val_loader = DataLoader(\n        val_dataset,\n        batch_size=batch_size,\n        collate_fn=customized_collate_fn,\n        shuffle=False,\n        drop_last=False,\n        num_workers=num_workers\n    )\n\n    #######################################\n    # 2. 사전 학습된 모델 로드 (Pre-trained Model)\n    #######################################\n\n    if test_mode:\n        # 테스트 모드용 초소형 더미 모델\n        BASE_CONFIG = {\n            \"vocab_size\": 50257,\n            \"context_length\": 120,\n            \"drop_rate\": 0.0,\n            \"qkv_bias\": False,\n            \"emb_dim\": 12,\n            \"n_layers\": 1,\n            \"n_heads\": 2\n        }\n        model = GPTModel(BASE_CONFIG)\n        model.eval()\n        device = \"cpu\"\n        CHOOSE_MODEL = \"Small test model\"\n\n    else:\n        # 실제 학습용 설정: GPT-2 Medium (355M)\n        BASE_CONFIG = {\n            \"vocab_size\": 50257,     \n            \"context_length\": 1024,  \n            \"drop_rate\": 0.0,        \n            \"qkv_bias\": True         \n        }\n\n        model_configs = {\n            \"gpt2-small (124M)\": {\"emb_dim\": 768, \"n_layers\": 12, \"n_heads\": 12},\n            \"gpt2-medium (355M)\": {\"emb_dim\": 1024, \"n_layers\": 24, \"n_heads\": 16},\n            \"gpt2-large (774M)\": {\"emb_dim\": 1280, \"n_layers\": 36, \"n_heads\": 20},\n            \"gpt2-xl (1558M)\": {\"emb_dim\": 1600, \"n_layers\": 48, \"n_heads\": 25},\n        }\n\n        CHOOSE_MODEL = \"gpt2-medium (355M)\"\n        BASE_CONFIG.update(model_configs[CHOOSE_MODEL])\n\n        # 로컬에 저장된 모델 가중치 파일 로드\n        model_name = \"gpt2-medium-355M.pth\"\n        model = load_gpt2_model(model_name, BASE_CONFIG)\n\n        model.eval()\n        model.to(device)\n\n    print(\"Loaded model:\", CHOOSE_MODEL)\n    print(50*\"-\")\n\n    #######################################\n    # 3. 모델 미세 조정 (Finetuning)\n    #######################################\n    print(\"Initial losses\")\n    # 학습 전 초기 손실값 확인\n    with torch.no_grad():\n        train_loss = calc_loss_loader(train_loader, model, device, num_batches=5)\n        val_loss = calc_loss_loader(val_loader, model, device, num_batches=5)\n\n    print(\"   Training loss:\", train_loss)\n    print(\"   Validation loss:\", val_loss)\n\n    start_time = time.time()\n    # 옵티마이저 설정 (AdamW)\n    optimizer = torch.optim.AdamW(model.parameters(), lr=0.00005, weight_decay=0.1)\n\n    num_epochs = 2\n\n    torch.manual_seed(123)\n    \n    # 실제 학습 수행 (previous_chapters.py에 정의된 함수 사용)\n    train_losses, val_losses, tokens_seen = train_model_simple(\n        model, train_loader, val_loader, optimizer, device,\n        num_epochs=num_epochs, eval_freq=5, eval_iter=5,\n        start_context=format_input(val_data[0]), tokenizer=tokenizer\n    )\n\n    end_time = time.time()\n    execution_time_minutes = (end_time - start_time) / 60\n    print(f\"Training completed in {execution_time_minutes:.2f} minutes.\")\n\n    # 학습 결과 시각화\n    epochs_tensor = torch.linspace(0, num_epochs, len(train_losses))\n    plot_losses(epochs_tensor, tokens_seen, train_losses, val_losses)\n    print(50*\"-\")\n\n    #######################################\n    # 4. 결과 저장 및 테스트\n    #######################################\n    print(\"Generating responses\")\n    # 테스트 데이터셋에 대해 모델 응답 생성\n    for i, entry in tqdm(enumerate(test_data), total=len(test_data)):\n\n        input_text = format_input(entry)\n\n        # 모델 생성 (Inference)\n        token_ids = generate(\n            model=model,\n            idx=text_to_token_ids(input_text, tokenizer).to(device),\n            max_new_tokens=256,\n            context_size=BASE_CONFIG[\"context_length\"],\n            eos_id=50256\n        )\n        generated_text = token_ids_to_text(token_ids, tokenizer)\n        \n        # 프롬프트 부분을 제거하고 응답 부분만 추출\n        response_text = generated_text[len(input_text):].replace(\"### Response:\", \"\").strip()\n\n        test_data[i][\"model_response\"] = response_text\n\n    # 생성된 응답을 포함하여 JSON 파일로 저S장\n    test_data_path = \"outputs/instruction-data-with-response-standalone.json\"\n    with open(test_data_path, \"w\") as file:\n        json.dump(test_data, file, indent=4) \n    print(f\"Responses saved as {test_data_path}\")\n\n    # 미세 조정된 모델 가중치 저장\n    file_name = f\"outputs/{re.sub(r'[ ()]', '', CHOOSE_MODEL) }-sft-standalone.pth\"\n    torch.save(model.state_dict(), file_name)\n    print(f\"Model saved as {file_name}\")"}, {"number": 2, "code_number": 2, "type": "code", "source": "main(test_mode=False)"}], "blanks": [{"id": "blank-ch7a-eos", "label": "Sequence 끝 pad token", "answer": "pad_token_id"}, {"id": "blank-ch7a-padding", "label": "Batch padding token", "answer": "pad_token_id"}, {"id": "blank-ch7a-input-shift", "label": "Input 마지막 token 제외", "answer": "-1"}]}, "Chapter_7_Exercise_Follow_Instructions_dpo.ipynb": {"page": "llm_chapter_7b_dpo_subjective_test", "cells": [{"number": 1, "code_number": 1, "type": "code", "source": "import os\nimport json\nimport time\nimport requests\nimport torch\nimport torch.nn.functional as F\nfrom torch.utils.data import Dataset, DataLoader\nfrom functools import partial\nimport tiktoken\n\n# ==========================================\n# [중요] 외부 모듈 의존성 처리\n# 이 코드는 책이나 튜토리얼의 일부로, 이전 챕터에서 정의된 모델(GPTModel)이 필요합니다.\n# ==========================================\ntry:\n    from previous_chapters import GPTModel, generate_and_print_sample, download_model\nexcept ImportError:\n    print(\"경고: 'previous_chapters' 모듈을 찾을 수 없습니다. GPTModel 등의 정의가 필요합니다.\")\n\n# ==========================================\n# 1. 설정 및 데이터 로드 유틸리티\n# 데이터를 인터넷에서 다운로드하거나 로컬에서 불러오는 기능을 담당합니다.\n# ==========================================\ndef download_and_load_file(file_path, url):\n    \"\"\"\n    지정된 경로에 파일이 없으면 URL에서 다운로드하고,\n    파일을 읽어 JSON 데이터를 반환합니다.\n    \"\"\"\n    if not os.path.exists(file_path):\n        os.makedirs(os.path.dirname(file_path), exist_ok=True)\n        response = requests.get(url, timeout=30)\n        response.raise_for_status()\n        with open(file_path, \"w\", encoding=\"utf-8\") as file:\n            file.write(response.text)\n    else:\n        with open(file_path, \"r\", encoding=\"utf-8\") as file:\n            text_data = file.read()\n    return json.loads(text_data)\n\n\ndef format_input(entry):\n    \"\"\"\n    JSON 데이터의 항목을 모델이 이해할 수 있는 프롬프트 형식으로 변환합니다.\n    (알파카(Alpaca) 데이터셋 스타일 포맷팅)\n    \"\"\"\n    instruction_text = (\n        f\"Below is an instruction that describes a task. \"\n        f\"Write a response that appropriately completes the request.\"\n        f\"\\n\\n### Instruction:\\n{entry['instruction']}\"\n    )\n    # 추가 입력(Input)이 있는 경우에만 붙임\n    input_text = f\"\\n\\n### Input:\\n{entry['input']}\" if entry[\"input\"] else \"\"\n    return instruction_text + input_text\n\n# ==========================================\n# 2. 데이터셋 및 Collate 함수 (DPO용)\n# DPO는 (프롬프트, 선택된 답변, 거부된 답변)의 쌍이 필요합니다.\n# ==========================================\nclass PreferenceDataset(Dataset):\n    def __init__(self, data, tokenizer):\n        self.data = data\n        self.encoded_texts = []\n        \n        # 데이터를 미리 토큰화(Tokenization)하여 저장합니다.\n        for entry in data:\n            prompt = format_input(entry)\n            rejected_response = entry[\"rejected\"] # 👎 덜 선호되는 답변\n            chosen_response = entry[\"chosen\"]     # 👍 더 선호되는 답변\n\n            # 프롬프트 부분만 따로 인코딩 (나중에 마스킹하기 위해 필요)\n            prompt_tokens = tokenizer.encode(prompt)\n            \n            # 프롬프트 + 답변 형태로 전체 문장을 인코딩\n            # TODO: 선호/비선호 응답 변수명을 채우세요.\n            # 힌트: 바로 위에서 만든 chosen_response와 rejected_response를 Response 뒤에 붙입니다.\n            # 예시: chosen 쪽은 chosen_response, rejected 쪽은 rejected_response를 사용합니다.\n            chosen_full_tokens = tokenizer.encode(f\"{prompt}\\n\\n### Response:\\n{[[BLANK:blank-ch7b-chosen]]}\")\n            rejected_full_tokens = tokenizer.encode(f\"{prompt}\\n\\n### Response:\\n{????}\")\n\n            self.encoded_texts.append({\n                \"prompt\": prompt_tokens,\n                \"chosen\": chosen_full_tokens,\n                \"rejected\": rejected_full_tokens,\n            })\n\n    def __getitem__(self, index):\n        return self.encoded_texts[index]\n\n    def __len__(self):\n        return len(self.data)\n\ndef custom_collate_fn(batch, pad_token_id=50256, allowed_max_length=None, mask_prompt_tokens=True, device=\"cpu\"):\n    \"\"\"\n    배치(Batch) 내의 데이터 길이를 맞추고(Padding), 마스크(Mask)를 생성하는 함수입니다.\n    \"\"\"\n    batch_data = {\n        \"prompt\": [],\n        \"chosen\": [],\n        \"rejected\": [],\n        \"rejected_mask\": [], # Loss 계산 시 무시할 부분 (패딩 등)\n        \"chosen_mask\": []\n    }\n\n    # 1. 배치 내에서 가장 긴 시퀀스 길이 찾기 (패딩을 위해)\n    max_length_common = 0\n    if batch:\n        for key in [\"chosen\", \"rejected\"]:\n            current_max = max(len(item[key]) + 1 for item in batch)\n            max_length_common = max(max_length_common, current_max)\n\n    # 2. 패딩 추가 및 마스크 생성\n    for item in batch:\n        prompt = torch.tensor(item[\"prompt\"])\n        batch_data[\"prompt\"].append(prompt)\n\n        for key in [\"chosen\", \"rejected\"]:\n            sequence = item[key]\n            # 최대 길이에 맞춰 패딩 토큰 추가\n            padded = sequence + [pad_token_id] * (max_length_common - len(sequence))\n            \n            # 기본 마스크: 데이터가 있는 곳은 1(True), 패딩은 0(False)\n            mask = torch.ones(len(padded)).bool()\n            mask[len(sequence):] = False  # 패딩 부분 마스킹\n\n            # [중요] 프롬프트 부분 마스킹 (선택적)\n            # DPO는 '답변'의 확률 차이를 학습하므로, 질문(Prompt) 부분은 Loss 계산에서 제외합니다.\n            # +2는 \\n\\n때문\n            if mask_prompt_tokens:\n                mask[:prompt.shape[0] + 2] = False \n\n            batch_data[key].append(torch.tensor(padded))\n            batch_data[f\"{key}_mask\"].append(mask)\n\n    # 3. 텐서 변환 및 디바이스(GPU/CPU) 이동\n    for key in [\"chosen\", \"rejected\", \"chosen_mask\", \"rejected_mask\"]:\n        tensor_stack = torch.stack(batch_data[key])\n        # 길이 제한이 있다면 자르기\n        if allowed_max_length is not None:\n            tensor_stack = tensor_stack[:, :allowed_max_length]\n        batch_data[key] = tensor_stack.to(device)\n\n    return batch_data\n\n# ==========================================\n# 3. DPO Loss 및 Log Probability 계산 함수\n# DPO의 핵심 수학적 로직이 들어있는 부분입니다.\n# ==========================================\ndef compute_logprobs(logits, labels, selection_mask=None):\n    \"\"\"\n    모델의 출력(logits)과 정답(labels)을 받아 해당 정답 토큰의 로그 확률을 계산합니다.\n    \"\"\"\n    # Auto-regressive 모델 특성상, 입력 [A, B, C]에 대해 예측은 [B, C, D]가 되므로 시프트(Shift)합니다.\n    # TODO: 자동회귀 시프트 인덱스를 채우세요.\n    # 힌트: labels는 1칸 앞당기고 logits는 마지막 시점을 제외해 정렬합니다.\n    labels = labels[:, ????:].clone()\n    logits = logits[:, :????, :]\n    \n    log_probs = F.log_softmax(logits, dim=-1)\n    \n    # 실제 정답 레이블에 해당하는 확률값만 추출 (gather 사용)\n    # TODO: gather의 input 텐서를 채우세요.\n    # 힌트: raw logits가 아닌 log_probs에서 정답 위치를 gather해야 합니다.\n    selected_log_probs = torch.gather(\n        input=????,\n        dim=-1,\n        index=labels.unsqueeze(-1)\n    ).squeeze(-1)\n\n    if selection_mask is not None:\n        # 마스크도 시프트하여 적용 (패딩이나 프롬프트 영역 무시)\n        mask = selection_mask[:, 1:].clone()\n        selected_log_probs = selected_log_probs * mask\n        \n        # 유효한 토큰들의 로그 확률 평균 계산\n        avg_log_prob = selected_log_probs.sum(-1) / mask.sum(-1)\n        return avg_log_prob\n    else:\n        return selected_log_probs.mean(-1)\n\ndef compute_dpo_loss(model_chosen_logprobs, model_rejected_logprobs, \n                     reference_chosen_logprobs, reference_rejected_logprobs, beta=0.1):\n    \"\"\"\n    DPO 손실 함수 계산:\n    Policy 모델이 Reference 모델보다 'chosen' 답변을 더 선호하고, 'rejected' 답변을 덜 선호하도록 유도합니다.\n    \n    beta: Reference 모델에서 얼마나 벗어날지 제어하는 하이퍼파라미터 (보통 0.1~0.5)\n    \"\"\"\n    # 모델의 (Chosen - Rejected) 로그 확률 차이\n    # TODO: 정책 모델 chosen 로그확률 변수를 채우세요.\n    # 힌트: chosen - rejected 순서로 빼야 preference 방향이 맞습니다.\n    model_logratios = ???? - model_rejected_logprobs\n    # 기준 모델의 (Chosen - Rejected) 로그 확률 차이\n    # TODO: 레퍼런스 모델 chosen 로그확률 변수를 채우세요.\n    # 힌트: reference도 chosen - rejected 순서를 동일하게 유지합니다.\n    reference_logratios = ???? - reference_rejected_logprobs\n    \n    # 두 비율의 차이 (Policy가 Reference보다 얼마나 더 잘 구분했는가)\n    # TODO: DPO logits 차감 대상을 채우세요.\n    # 힌트: policy 비율에서 reference 비율을 빼는 형태입니다.\n    logits = model_logratios - ????\n    \n    # Sigmoid 후 음수 로그 (Cross Entropy와 유사) -> 이 값을 최소화하면 선호도 차이가 극대화됨\n    # TODO: DPO 손실 함수명을 채우세요.\n    # 힌트: beta * logits에 logsigmoid를 적용해 손실을 계산합니다.\n    losses = -F.????(beta * logits)\n    \n    # 학습 추적용 보상(Reward) 계산 (실제 학습엔 안 쓰이고 로깅용)\n    chosen_rewards = (model_chosen_logprobs - reference_chosen_logprobs).detach()\n    rejected_rewards = (model_rejected_logprobs - reference_rejected_logprobs).detach()\n    \n    return losses.mean(), chosen_rewards.mean(), rejected_rewards.mean()\n\ndef compute_dpo_loss_batch(batch, policy_model, reference_model, beta):\n    \"\"\"\n    하나의 배치에 대해 전체 DPO 과정을 수행하는 헬퍼 함수\n    \"\"\"\n    # 1. 학습 중인 모델(Policy Model)의 로그 확률 계산 (기울기 계산 O)\n    policy_chosen_log_probas = compute_logprobs(\n        logits=policy_model(batch[\"chosen\"]),\n        labels=batch[\"chosen\"],\n        selection_mask=batch[\"chosen_mask\"]\n    )\n    policy_rejected_log_probas = compute_logprobs(\n        logits=policy_model(batch[\"rejected\"]),\n        labels=batch[\"rejected\"],\n        selection_mask=batch[\"rejected_mask\"]\n    )\n    \n    # 2. 기준 모델(Reference Model)의 로그 확률 계산 (기울기 계산 X -> 메모리 절약)\n    with torch.no_grad():\n        ref_chosen_log_probas = compute_logprobs(\n            logits=reference_model(batch[\"chosen\"]),\n            labels=batch[\"chosen\"],\n            selection_mask=batch[\"chosen_mask\"]\n        )\n        ref_rejected_log_probas = compute_logprobs(\n            logits=reference_model(batch[\"rejected\"]),\n            labels=batch[\"rejected\"],\n            selection_mask=batch[\"rejected_mask\"]\n        )\n\n    # 3. 최종 Loss 계산\n    loss, chosen_rewards, rejected_rewards = compute_dpo_loss(\n        model_chosen_logprobs=policy_chosen_log_probas,\n        model_rejected_logprobs=policy_rejected_log_probas,\n        reference_chosen_logprobs=ref_chosen_log_probas,\n        reference_rejected_logprobs=ref_rejected_log_probas,\n        beta=beta\n    )\n    return loss, chosen_rewards, rejected_rewards\n\n# ==========================================\n# 4. 평가 및 학습 루프\n# 실제 모델 학습을 돌리는 메인 루프입니다.\n# ==========================================\ndef evaluate_dpo_loss_loader(policy_model, reference_model, train_loader, val_loader, beta, eval_iter):\n    \"\"\"\n    학습 중간에 모델 성능을 평가(Validation)하는 함수\n    \"\"\"\n    policy_model.eval() # 평가 모드 전환 (Dropout 등 비활성화)\n    with torch.no_grad():\n        # 로더를 순회하며 평균 Loss 계산하는 내부 함수\n        def compute_loader_metric(loader):\n            total_loss, total_chosen, total_rejected = 0., 0., 0.\n            num_batches = min(eval_iter, len(loader))\n            if num_batches == 0: return float(\"nan\"), float(\"nan\"), float(\"nan\")\n            \n            for i, batch in enumerate(loader):\n                if i >= num_batches: break\n                loss, chosen, rejected = compute_dpo_loss_batch(batch, policy_model, reference_model, beta)\n                total_loss += loss.item()\n                total_chosen += chosen.item()\n                total_rejected += rejected.item()\n            return total_loss/num_batches, total_chosen/num_batches, total_rejected/num_batches\n\n        train_loss, train_chosen, train_rejected = compute_loader_metric(train_loader)\n        val_loss, val_chosen, val_rejected = compute_loader_metric(val_loader)\n\n    policy_model.train() # 다시 학습 모드로 전환\n    return {\n        \"train_loss\": train_loss,\n        \"train_chosen_reward\": train_chosen,\n        \"train_rejected_reward\": train_rejected,\n        \"val_loss\": val_loss,\n        \"val_chosen_reward\": val_chosen,\n        \"val_rejected_reward\": val_rejected\n    }\n\ndef train_model_dpo_simple(policy_model, reference_model, train_loader, val_loader, \n                           optimizer, num_epochs, beta, eval_freq, eval_iter, start_context, tokenizer):\n    \"\"\"\n    전체 학습 과정을 관리하는 함수\n    \"\"\"\n    tracking = {\"train_losses\": [], \"val_losses\": [], \"tokens_seen\": []}\n    tokens_seen, global_step = 0, -1\n\n    for epoch in range(num_epochs):\n        policy_model.train() # 학습 모드 시작\n        for batch in train_loader:\n            optimizer.zero_grad() # 이전 기울기 초기화\n            \n            # Loss 계산\n            loss, chosen_rewards, rejected_rewards = compute_dpo_loss_batch(\n                batch=batch, policy_model=policy_model, reference_model=reference_model, beta=beta\n            )\n            \n            loss.backward() # 역전파 (기울기 계산)\n            optimizer.step() # 가중치 업데이트\n            \n            tokens_seen += batch[\"chosen\"].numel()\n            global_step += 1\n\n            # 평가 주기마다 성능 측정 및 출력\n            if global_step % eval_freq == 0:\n                res = evaluate_dpo_loss_loader(\n                    policy_model, reference_model, train_loader, val_loader, beta, eval_iter\n                )\n                tracking[\"train_losses\"].append(res[\"train_loss\"])\n                tracking[\"val_losses\"].append(res[\"val_loss\"])\n                tracking[\"tokens_seen\"].append(tokens_seen)\n                \n                # Margin = Chosen Reward - Rejected Reward (클수록 좋음, 모델이 정답을 오답보다 더 선호한다는 뜻)\n                print(f\"Ep {epoch+1} (Step {global_step:06d}): \"\n                      f\"Train loss {res['train_loss']:.3f}, Val loss {res['val_loss']:.3f}, \"\n                      f\"Train Margin {res['train_chosen_reward']-res['train_rejected_reward']:.3f}\")\n\n        # 에포크가 끝날 때마다 샘플 생성하여 육안으로 확인\n        generate_and_print_sample(model=policy_model, tokenizer=tokenizer, device=loss.device, start_context=start_context)\n\n    return tracking"}, {"number": 2, "code_number": null, "type": "markdown", "source": "### 💡 주요 핵심 포인트\n\n1. **DPO의 원리**: 일반적인 학습과 달리 **두 개의 모델**이 필요합니다.\n* `policy_model`: 학습이 되어 업데이트되는 모델 (우리가 훈련시키는 모델).\n* `reference_model`: 학습되지 않고 고정된 상태로 비교 기준이 되는 모델 (보통 SFT가 완료된 모델 사용).\n\n\n2. **데이터 구성**: `(Prompt, Chosen, Rejected)` 세 가지가 한 세트입니다. 모델이 `Chosen`(선호) 쪽으로 확률을 높이고 `Rejected`(비선호) 쪽으로 확률을 낮추도록 유도합니다.\n3. **마스킹(Masking)**: `custom_collate_fn`에서 프롬프트 부분을 `False`로 마스킹합니다. 모델이 질문(Prompt)을 생성하는 능력은 평가하지 않고, 질문에 대한 **답변(Response)** 부분의 확률만을 가지고 Loss를 계산하기 위함입니다."}, {"number": 3, "code_number": 2, "type": "code", "source": "# ==========================================\n# 5. 메인 실행 코드\n# ==========================================\n# 설정\ndevice = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\nprint(f\"Using device: {device}\")\n\ntokenizer = tiktoken.get_encoding(\"gpt2\")\n\n# 데이터 로드\nfile_path = \"datas/instruction-data-with-preference.json\"\nurl = \"https://raw.githubusercontent.com/rasbt/LLMs-from-scratch/main/ch07/04_preference-tuning-with-dpo/instruction-data-with-preference.json\"\ndata = download_and_load_file(file_path, url)\n\n# 데이터 분할\ntrain_portion = int(len(data) * 0.85)\ntest_portion = int(len(data) * 0.1)\ntrain_data = data[:train_portion]\ntest_data = data[train_portion:train_portion + test_portion]\nval_data = data[train_portion + test_portion:]\n\n# DataLoader 생성\ncustomized_collate_fn = partial(\n    custom_collate_fn, device=device, mask_prompt_tokens=True, allowed_max_length=1024\n)\n\nbatch_size = 8\ntrain_loader = DataLoader(PreferenceDataset(train_data, tokenizer), batch_size=batch_size, \n                            collate_fn=customized_collate_fn, shuffle=True, drop_last=True)\nval_loader = DataLoader(PreferenceDataset(val_data, tokenizer), batch_size=batch_size, \n                        collate_fn=customized_collate_fn, shuffle=False)\n\n# 모델 설정 (SFT 모델 로드)\nBASE_CONFIG = {\n    \"vocab_size\": 50257, \"context_length\": 1024, \"drop_rate\": 0.0, \"qkv_bias\": True,\n    \"emb_dim\": 1024, \"n_layers\": 24, \"n_heads\": 16 # gpt2-medium config\n}\n\nfile_name = \"gpt2-medium-355M.pth\"\nmodel_path = f\"./models/gpt2/{file_name}\"\ndownload_model(file_name, model_path)\n\n# Policy Model (학습 대상)\npolicy_model = GPTModel(BASE_CONFIG)\npolicy_model.load_state_dict(torch.load(model_path, map_location=\"cpu\", weights_only=True))\npolicy_model.to(device)\n\n# Reference Model (고정 기준점)\nreference_model = GPTModel(BASE_CONFIG)\nreference_model.load_state_dict(torch.load(model_path, map_location=\"cpu\", weights_only=True))\nreference_model.to(device)\nreference_model.eval()\n\n# 학습 시작\noptimizer = torch.optim.AdamW(policy_model.parameters(), lr=5e-6, weight_decay=0.01)\n\nstart_time = time.time()\nnum_epochs = 1\ntracking = train_model_dpo_simple(\n    policy_model=policy_model,\n    reference_model=reference_model,\n    train_loader=train_loader,\n    val_loader=val_loader,\n    optimizer=optimizer,\n    num_epochs=num_epochs,\n    beta=0.1,\n    eval_freq=5,\n    eval_iter=5,\n    start_context=format_input(val_data[2]),\n    tokenizer=tokenizer\n)\nprint(f\"Training completed in {(time.time() - start_time) / 60:.2f} minutes.\")"}, {"number": 4, "code_number": 3, "type": "code", "source": "from previous_chapters import plot_losses\n# 대안:\n# from llms_from_scratch.ch05 import plot_losses\nnum_epochs=1\n\nepochs_tensor = torch.linspace(0, num_epochs, len(tracking[\"train_losses\"]))\nplot_losses(\n    epochs_seen=epochs_tensor,\n    tokens_seen=tracking[\"tokens_seen\"],\n    train_losses=tracking[\"train_losses\"],\n    val_losses=tracking[\"val_losses\"],\n    label=\"loss\"\n)"}, {"number": 5, "code_number": 4, "type": "code", "source": "from previous_chapters import (\n    generate,\n    text_to_token_ids,\n    token_ids_to_text\n)\n\ntorch.manual_seed(123)\n\n\nfor entry in test_data[:3]:\n\n    input_text = format_input(entry)\n\n    token_ids = generate(\n        model=reference_model,\n        idx=text_to_token_ids(input_text, tokenizer).to(device),\n        max_new_tokens=256,\n        context_size=BASE_CONFIG[\"context_length\"],\n        eos_id=50256\n    )\n    generated_text = token_ids_to_text(token_ids, tokenizer)\n    reference_response_text = (\n        generated_text[len(input_text):]\n        .replace(\"### Response:\", \"\")\n        .strip()\n    )\n\n    token_ids = generate(\n        model=policy_model,\n        idx=text_to_token_ids(input_text, tokenizer).to(device),\n        max_new_tokens=256,\n        context_size=BASE_CONFIG[\"context_length\"],\n        eos_id=50256\n    )\n    generated_text = token_ids_to_text(token_ids, tokenizer)\n    policy_response_text = (\n        generated_text[len(input_text):]\n        .replace(\"### Response:\", \"\")\n        .strip()\n    )\n\n    print(input_text)\n    print(f\"\\nCorrect response:\\n>> {entry['output']}\")\n    print(f\"\\nReference model response:\\n>> {reference_response_text.strip()}\")\n    print(f\"\\nPolicy model response:\\n>> {policy_response_text.strip()}\")\n    print(\"\\n-------------------------------------\\n\")"}, {"number": 6, "code_number": 5, "type": "code", "source": ""}], "blanks": [{"id": "blank-ch7b-chosen", "label": "Chosen response 연결", "answer": "entry[\"chosen\"]"}, {"id": "blank-ch7b-rejected", "label": "Rejected response 연결", "answer": "entry[\"rejected\"]"}, {"id": "blank-ch7b-label-shift", "label": "DPO label next-token shift", "answer": "1"}]}};
